-- Name: FUNCTION update_bulk_operation_progress(p_operation_id uuid, p_completed_increment integer, p_failed_increment integer); Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON FUNCTION admin_dashboard.update_bulk_operation_progress(p_operation_id uuid, p_completed_increment integer, p_failed_increment integer) IS 'Actualiza el progreso de una operación bulk incrementando contadores y actualizando estado automáticamente';


--
-- Name: cleanup_old_system_logs(integer); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.cleanup_old_system_logs(p_retention_days integer DEFAULT 90) RETURNS TABLE(deleted_count integer, status_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'audit_logging'
    AS $$
DECLARE
    v_deleted_count INTEGER := 0;
    v_cutoff_date TIMESTAMP WITHOUT TIME ZONE;
    v_message TEXT;
BEGIN
    -- Calculate cutoff date
    v_cutoff_date := NOW() - (p_retention_days || ' days')::INTERVAL;

    -- Delete old system logs
    DELETE FROM audit_logging.system_logs
    WHERE created_at < v_cutoff_date;

    -- FIX: Usar GET DIAGNOSTICS para obtener el conteo de registros eliminados
    -- BUG anterior: FOUND::INTEGER * COUNT(*) despues del DELETE no funcionaba correctamente
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    -- Vacuum analyze to reclaim space
    VACUUM ANALYZE audit_logging.system_logs;

    v_message := FORMAT('Successfully deleted %L log entries older than %L days', v_deleted_count, p_retention_days);

    RETURN QUERY SELECT v_deleted_count, v_message;

EXCEPTION WHEN OTHERS THEN
    v_message := FORMAT('Error during cleanup: %s', SQLERRM);
    RETURN QUERY SELECT 0, v_message;
END;
$$;


ALTER FUNCTION audit_logging.cleanup_old_system_logs(p_retention_days integer) OWNER TO postgres;

--
-- Name: FUNCTION cleanup_old_system_logs(p_retention_days integer); Type: COMMENT; Schema: audit_logging; Owner: postgres
--

COMMENT ON FUNCTION audit_logging.cleanup_old_system_logs(p_retention_days integer) IS 'Maintenance function to cleanup old system logs entries for performance and storage optimization.
Parameters:
  - p_retention_days: Number of days to retain logs (default: 90)
Returns:
  - deleted_count: Number of records deleted
  - status_message: Operation status message';


--
-- Name: cleanup_old_user_activity(integer); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.cleanup_old_user_activity(p_retention_days integer DEFAULT 180) RETURNS TABLE(deleted_count integer, status_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'audit_logging'
    AS $$
DECLARE
    v_deleted_count INTEGER := 0;
    v_cutoff_date TIMESTAMP WITHOUT TIME ZONE;
    v_message TEXT;
BEGIN
    -- Calculate cutoff date
    v_cutoff_date := NOW() - (p_retention_days || ' days')::INTERVAL;

    -- Delete old user activity records
    DELETE FROM audit_logging.user_activity_logs
    WHERE created_at < v_cutoff_date;

    -- FIX: Usar GET DIAGNOSTICS para obtener el conteo de registros eliminados
    -- BUG anterior: COUNT(*) despues del DELETE siempre retornaba 0
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    -- Optimize table after bulk delete
    VACUUM ANALYZE audit_logging.user_activity_logs;

    v_message := FORMAT('Successfully deleted %L user activity records older than %L days', v_deleted_count, p_retention_days);

    RETURN QUERY SELECT v_deleted_count, v_message;

EXCEPTION WHEN OTHERS THEN
    v_message := FORMAT('Error during cleanup: %s', SQLERRM);
    RETURN QUERY SELECT 0, v_message;
END;
$$;


