--
-- Name: log_system_event(text, text, jsonb, text); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.log_system_event(p_event_type text, p_event_source text, p_event_data jsonb DEFAULT NULL::jsonb, p_severity text DEFAULT 'INFO'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'audit_logging'
    AS $$
DECLARE
    v_event_id UUID;
    v_valid_severity BOOLEAN;
    v_log_level TEXT;
BEGIN
    -- Validate severity level
    v_valid_severity := p_severity IN ('DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL');

    IF NOT v_valid_severity THEN
        RAISE EXCEPTION 'Invalid severity level: %', p_severity;
    END IF;

    -- Map severity to system_logs.log_level CHECK values (TRACE, DEBUG, INFO, WARN, ERROR, FATAL)
    v_log_level := CASE p_severity
        WHEN 'WARNING' THEN 'WARN'
        WHEN 'CRITICAL' THEN 'FATAL'
        ELSE p_severity
    END;

    -- Insert system event into system_logs with correct column names
    INSERT INTO audit_logging.system_logs (
        log_level,
        message,
        module_name,
        extra_data,
        created_at
    ) VALUES (
        v_log_level,
        p_event_type,
        p_event_source,
        COALESCE(p_event_data, '{}'::jsonb),
        NOW()
    )
    RETURNING id INTO v_event_id;

    -- Return the created event ID
    RETURN v_event_id;

EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Error logging system event: %', SQLERRM;
    RETURN NULL;
END;
$$;


ALTER FUNCTION audit_logging.log_system_event(p_event_type text, p_event_source text, p_event_data jsonb, p_severity text) OWNER TO postgres;

--
-- Name: FUNCTION log_system_event(p_event_type text, p_event_source text, p_event_data jsonb, p_severity text); Type: COMMENT; Schema: audit_logging; Owner: postgres
--

COMMENT ON FUNCTION audit_logging.log_system_event(p_event_type text, p_event_source text, p_event_data jsonb, p_severity text) IS 'Logs system events for monitoring and debugging purposes.
Parameters:
  - p_event_type: Type of event mapped to message column (e.g., ''DATABASE_BACKUP_START'', ''API_ERROR'')
  - p_event_source: Source component mapped to module_name column
  - p_event_data: Optional JSONB data mapped to extra_data column
  - p_severity: DEBUG, INFO, WARNING, ERROR, CRITICAL (mapped to log_level: WARNING→WARN, CRITICAL→FATAL)
Returns:
  - UUID of the created system log entry, or NULL on error
Example:
  SELECT log_system_event(
    ''API_REQUEST_TIMEOUT''::TEXT,
    ''auth_service''::TEXT,
    jsonb_build_object(''user_id'', 123, ''endpoint'', ''/api/auth/login''),
    ''WARNING''::TEXT
  );';


--
-- Name: resolve_pending_initialization(uuid, uuid, text); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.resolve_pending_initialization(p_user_id uuid, p_resolved_by uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE audit_logging.pending_user_initializations
    SET status = 'resolved',
        resolved_at = gamilit.now_mexico(),
        resolved_by = p_resolved_by,
        resolution_notes = p_notes,
        updated_at = gamilit.now_mexico()
    WHERE user_id = p_user_id
      AND status IN ('pending', 'retrying', 'failed');

    RETURN FOUND;
END;
$$;


ALTER FUNCTION audit_logging.resolve_pending_initialization(p_user_id uuid, p_resolved_by uuid, p_notes text) OWNER TO postgres;

