--

COMMENT ON FUNCTION auth_management.assign_role_to_user(p_user_id uuid, p_role auth_management.gamilit_role, p_permissions jsonb, p_assigned_by uuid) IS 'Asigna un rol a un usuario con validaciones de seguridad y auditoría';


--
-- Name: ensure_profile_name(); Type: FUNCTION; Schema: auth_management; Owner: postgres
--

CREATE FUNCTION auth_management.ensure_profile_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  email_prefix TEXT;
  extracted_name TEXT;
BEGIN
  -- Si first_name está vacío o es NULL, extraer del email
  IF NEW.first_name IS NULL OR TRIM(NEW.first_name) = '' THEN
    -- Obtener parte antes del @
    email_prefix := SPLIT_PART(NEW.email, '@', 1);

    -- Limpiar: quitar números, reemplazar puntos/guiones por espacios, capitalizar
    extracted_name := INITCAP(
      TRIM(
        REGEXP_REPLACE(
          REGEXP_REPLACE(
            email_prefix,
            '[0-9]+', '', 'g'  -- Quitar números
          ),
          '[._-]+', ' ', 'g'   -- Puntos/guiones a espacios
        )
      )
    );

    -- Si después de limpiar queda vacío, usar 'Usuario'
    IF extracted_name = '' THEN
      extracted_name := 'Usuario';
    END IF;

    NEW.first_name := extracted_name;
  END IF;

  -- Si last_name está vacío o es NULL, poner valor por defecto
  IF NEW.last_name IS NULL OR TRIM(NEW.last_name) = '' THEN
    NEW.last_name := 'Usuario';
  END IF;

  -- Siempre computar full_name como concatenación de first_name + last_name
  NEW.full_name := TRIM(COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''));

  RETURN NEW;
END;
$$;


ALTER FUNCTION auth_management.ensure_profile_name() OWNER TO postgres;

--
-- Name: FUNCTION ensure_profile_name(); Type: COMMENT; Schema: auth_management; Owner: postgres
--

COMMENT ON FUNCTION auth_management.ensure_profile_name() IS 'Asegura first_name/last_name/full_name tengan valores. Extrae del email si es necesario. Previene "Unknown Student" en la UI.';


--
-- Name: get_user_role(uuid); Type: FUNCTION; Schema: auth_management; Owner: postgres
--

CREATE FUNCTION auth_management.get_user_role(p_user_id uuid DEFAULT NULL::uuid) RETURNS auth_management.gamilit_role
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_role auth_management.gamilit_role;
    v_user_id uuid;
BEGIN
    -- Use provided user_id or get current user
    v_user_id := COALESCE(p_user_id, gamilit.get_current_user_id());

    IF v_user_id IS NULL THEN
        RETURN 'student'::auth_management.gamilit_role;
    END IF;

    -- Get highest privilege role (super_admin > admin_teacher > student)
    SELECT role INTO v_role
    FROM auth_management.user_roles
    WHERE user_id = v_user_id
    AND is_active = true
    ORDER BY
        CASE role
            WHEN 'super_admin' THEN 1
            WHEN 'admin_teacher' THEN 2
            WHEN 'student' THEN 3
        END
    LIMIT 1;

    -- Default to student if no role found
    RETURN COALESCE(v_role, 'student'::auth_management.gamilit_role);
END;
$$;


ALTER FUNCTION auth_management.get_user_role(p_user_id uuid) OWNER TO postgres;

