COMMENT ON FUNCTION communication.create_conversation(p_title character varying, p_conversation_type character varying, p_created_by uuid, p_participant_ids uuid[], p_classroom_id uuid) IS 'Create a new conversation with initial participants. Creator becomes owner.
Usage: SELECT communication.create_conversation(''Title'', ''group'', creator_uuid, ARRAY[user1, user2]);';


--
-- Name: get_conversation_participants(uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.get_conversation_participants(p_conversation_id uuid) RETURNS TABLE(participant_id uuid, user_id uuid, display_name character varying, avatar_url character varying, role character varying, joined_at timestamp with time zone, is_active boolean, nickname character varying)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        cp.id AS participant_id,
        cp.user_id,
        p.display_name,
        p.avatar_url,
        cp.role,
        cp.joined_at,
        cp.is_active,
        cp.nickname
    FROM communication.conversation_participants cp
    JOIN auth_management.profiles p ON p.id = cp.user_id
    WHERE cp.conversation_id = p_conversation_id
    ORDER BY
        CASE cp.role
            WHEN 'owner' THEN 1
            WHEN 'admin' THEN 2
            ELSE 3
        END,
        cp.joined_at ASC;
END;
$$;


