--
-- Name: get_user_conversations(uuid, boolean); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.get_user_conversations(p_user_id uuid, p_include_archived boolean DEFAULT false) RETURNS TABLE(conversation_id uuid, title character varying, conversation_type character varying, last_message_at timestamp with time zone, last_message_preview text, unread_count integer, is_muted boolean, pin_order integer, participant_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        c.id AS conversation_id,
        c.title,
        c.conversation_type,
        c.last_message_at,
        c.last_message_preview,
        cp.unread_count,
        cp.is_muted,
        cp.pin_order,
        (SELECT COUNT(*) FROM communication.conversation_participants cp2
         WHERE cp2.conversation_id = c.id AND cp2.is_active = TRUE) AS participant_count
    FROM communication.conversation_participants cp
    JOIN communication.conversations c ON c.id = cp.conversation_id
    WHERE cp.user_id = p_user_id
      AND cp.is_active = TRUE
      AND (p_include_archived = TRUE OR c.is_archived = FALSE)
    ORDER BY
        cp.pin_order NULLS LAST,
        c.last_message_at DESC NULLS LAST;
END;
$$;


