Usage: SELECT * FROM communication.get_user_conversations(user_uuid);';


--
-- Name: get_user_unread_count(uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.get_user_unread_count(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(DISTINCT mp.message_id)
    INTO v_count
    FROM communication.message_participants mp
    WHERE mp.user_id = p_user_id
      AND mp.is_read = FALSE
      AND mp.role IN ('recipient', 'cc');

    RETURN COALESCE(v_count, 0);
END;
$$;


