--
-- Name: increment_unread_for_conversation(uuid, uuid, text); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.increment_unread_for_conversation(p_conversation_id uuid, p_sender_id uuid, p_message_preview text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    -- Update unread count for all active participants except sender
    UPDATE communication.conversation_participants
    SET unread_count = unread_count + 1,
        updated_at = NOW()
    WHERE conversation_id = p_conversation_id
      AND user_id != p_sender_id
      AND is_active = TRUE;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    -- Update conversation last message info
    UPDATE communication.conversations
    SET last_message_at = NOW(),
        last_message_preview = p_message_preview,
        message_count = message_count + 1,
        updated_at = NOW()
    WHERE id = p_conversation_id;

    RETURN v_updated;
END;
$$;


