--
-- Name: update_message_tracking_fields(); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.update_message_tracking_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();

    -- Track edits
    IF OLD.content IS DISTINCT FROM NEW.content THEN
        NEW.edited_at = NOW();
        NEW.edit_count = COALESCE(OLD.edit_count, 0) + 1;
    END IF;

    -- Auto-set read_at when is_read changes to true
    IF NEW.is_read = TRUE AND OLD.is_read = FALSE THEN
        NEW.read_at = NOW();
    END IF;

    -- Auto-set deleted_at when is_deleted changes to true
    IF NEW.is_deleted = TRUE AND OLD.is_deleted = FALSE THEN
        NEW.deleted_at = NOW();
    END IF;

    -- Auto-set flagged_at when is_flagged changes to true
    IF NEW.is_flagged = TRUE AND OLD.is_flagged = FALSE THEN
        NEW.flagged_at = NOW();
    END IF;

    RETURN NEW;
END;
$$;


