--
-- Name: apply_moderation_rules(uuid, text, character varying); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying) RETURNS TABLE(rule_matched boolean, rule_id uuid, rule_name character varying, action character varying, severity character varying, auto_executed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_matched BOOLEAN;
    v_has_matches BOOLEAN := false;
BEGIN
    -- Si no hay contenido, no hay nada que moderar
    IF p_content_text IS NULL OR p_content_text = '' THEN
        RETURN QUERY SELECT false, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, false;
        RETURN;
    END IF;

    -- Iterar sobre reglas activas ordenadas por prioridad y severidad
    FOR v_rule IN
        SELECT *
        FROM content_management.moderation_rules
        WHERE is_active = true
          AND target_entity = p_entity_type
        ORDER BY priority DESC, severity DESC, created_at ASC
    LOOP
        v_matched := false;

        -- Evaluar según tipo de regla
        CASE v_rule.rule_type
            WHEN 'keyword' THEN
                v_matched := content_management.check_keyword_rule(
                    p_content_text,
                    v_rule.rule_config
                );

            WHEN 'pattern' THEN
                v_matched := content_management.check_pattern_rule(
                    p_content_text,
                    v_rule.rule_config
                );

            WHEN 'length' THEN
                -- Verificar longitud del texto
                DECLARE
                    v_min_length INTEGER;
                    v_max_length INTEGER;
                    v_text_length INTEGER;
                BEGIN
                    v_min_length := COALESCE((v_rule.rule_config->>'min_length')::INTEGER, 0);
                    v_max_length := COALESCE((v_rule.rule_config->>'max_length')::INTEGER, 999999);
                    v_text_length := LENGTH(p_content_text);

                    v_matched := v_text_length < v_min_length OR v_text_length > v_max_length;
                END;

            ELSE
                -- Tipo de regla no soportado
                CONTINUE;
        END CASE;

        -- Si la regla coincidió, aplicar acción
        IF v_matched THEN
            v_has_matches := true;

            -- Aplicar acción según el tipo
            IF v_rule.action = 'flag' THEN
                -- Flaggear contenido para revisión
                INSERT INTO content_management.flagged_content (
                    content_id,
                    flagged_by_system,
                    reason,
                    priority,
                    status,
                    created_at
                ) VALUES (
                    p_content_id,
                    true,
                    'Auto-moderación: ' || v_rule.rule_name,
                    v_rule.severity,
                    'pending',
                    gamilit.now_mexico()
                )
                ON CONFLICT (content_id) DO UPDATE
                SET
                    reason = EXCLUDED.reason,
                    priority = EXCLUDED.priority,
                    updated_at = gamilit.now_mexico();

            ELSIF v_rule.action = 'block' AND v_rule.auto_execute THEN
                -- Bloquear contenido automáticamente
                -- Nota: Esto requiere que exista una tabla 'content' o similar
                -- con una columna 'status'. Ajustar según estructura real.
                -- Por ahora solo lo flaggeamos con alta prioridad
                INSERT INTO content_management.flagged_content (
                    content_id,
                    flagged_by_system,
                    reason,
                    priority,
                    status,
                    created_at
                ) VALUES (
                    p_content_id,
                    true,
                    'AUTO-BLOCKED: ' || v_rule.rule_name,
                    'critical',
                    'blocked',
                    gamilit.now_mexico()
                )
                ON CONFLICT (content_id) DO UPDATE
                SET
                    reason = EXCLUDED.reason,
                    status = 'blocked',
                    updated_at = gamilit.now_mexico();

            ELSIF v_rule.action = 'notify' THEN
                -- Enviar notificación a moderadores
                -- (Aquí se puede integrar con el sistema de notificaciones)
                INSERT INTO content_management.flagged_content (
                    content_id,
                    flagged_by_system,
                    reason,
                    priority,
                    status,
                    created_at
                ) VALUES (
                    p_content_id,
                    true,
                    'NOTIFY: ' || v_rule.rule_name,
                    v_rule.severity,
                    'review_required',
                    gamilit.now_mexico()
                )
                ON CONFLICT (content_id) DO UPDATE
                SET
                    reason = EXCLUDED.reason,
                    updated_at = gamilit.now_mexico();
            END IF;

            -- Retornar información del match
            RETURN QUERY SELECT
                true,
                v_rule.id,
                v_rule.rule_name::VARCHAR,
                v_rule.action::VARCHAR,
                v_rule.severity::VARCHAR,
                v_rule.auto_execute;

            -- Si la regla se auto-ejecutó y no requiere más revisión, detener
            IF v_rule.auto_execute AND NOT v_rule.require_review THEN
                RETURN;
            END IF;
        END IF;
    END LOOP;

    -- Si no hubo matches, retornar registro con false
    IF NOT v_has_matches THEN
        RETURN QUERY SELECT
            false,
            NULL::UUID,
            NULL::VARCHAR,
            NULL::VARCHAR,
            NULL::VARCHAR,
            false;
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION content_management.apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying) OWNER TO postgres;

--
-- Name: FUNCTION apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying); Type: COMMENT; Schema: content_management; Owner: postgres
--

COMMENT ON FUNCTION content_management.apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying) IS 'Aplica todas las reglas de moderación activas a un contenido y ejecuta las acciones correspondientes';


--
-- Name: auto_moderate_content(uuid, text, character varying); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.auto_moderate_content(p_content_id uuid, p_content_text text, p_entity_type character varying DEFAULT 'content'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_results RECORD;
    v_matches JSONB := '[]'::jsonb;
    v_has_critical BOOLEAN := false;
    v_should_block BOOLEAN := false;
BEGIN
    -- Aplicar reglas de moderación
    FOR v_results IN
        SELECT *
        FROM content_management.apply_moderation_rules(
            p_content_id,
            p_content_text,
            p_entity_type
        )
        WHERE rule_matched = true
    LOOP
        -- Agregar match al resultado
        v_matches := v_matches || jsonb_build_object(
            'rule_id', v_results.rule_id,
            'rule_name', v_results.rule_name,
            'action', v_results.action,
            'severity', v_results.severity,
            'auto_executed', v_results.auto_executed
        );

        -- Verificar si hay reglas críticas
        IF v_results.severity = 'critical' THEN
            v_has_critical := true;
        END IF;

        -- Verificar si debe bloquearse
        IF v_results.action = 'block' AND v_results.auto_executed THEN
            v_should_block := true;
        END IF;
    END LOOP;

    -- Retornar resumen en JSON
    RETURN jsonb_build_object(
        'content_id', p_content_id,
        'moderated', jsonb_array_length(v_matches) > 0,
        'matches_count', jsonb_array_length(v_matches),
        'has_critical', v_has_critical,
        'should_block', v_should_block,
        'matches', v_matches
    );
END;
$$;


