--
-- Name: log_ml_prediction(character varying, character varying, uuid, jsonb, jsonb, numeric, integer, boolean, uuid, uuid, uuid); Type: FUNCTION; Schema: data_warehouse; Owner: postgres
--

CREATE FUNCTION data_warehouse.log_ml_prediction(p_model_type character varying, p_model_version character varying, p_student_id uuid, p_input_features jsonb, p_output jsonb, p_confidence numeric, p_latency_ms integer, p_cached boolean DEFAULT false, p_classroom_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prediction_id UUID;
    v_risk_level VARCHAR(20);
    v_predicted_score DECIMAL(5, 2);
BEGIN
    -- Extract risk_level if present
    v_risk_level := p_output->>'riskLevel';

    -- Extract predicted score if present
    IF p_output ? 'predictedScore' THEN
        v_predicted_score := (p_output->>'predictedScore')::DECIMAL(5, 2);
    END IF;

    INSERT INTO data_warehouse.ml_prediction_logs (
        model_type,
        model_version,
        student_id,
        classroom_id,
        tenant_id,
        input_features_json,
        output_json,
        confidence,
        risk_level,
        predicted_score,
        latency_ms,
        cached,
        created_by
    ) VALUES (
        p_model_type,
        p_model_version,
        p_student_id,
        p_classroom_id,
        p_tenant_id,
        p_input_features,
        p_output,
        p_confidence,
        v_risk_level,
        v_predicted_score,
        p_latency_ms,
        p_cached,
        p_created_by
    )
    RETURNING prediction_id INTO v_prediction_id;

    RETURN v_prediction_id;
END;
$$;


