--
-- Name: set_active_model_version(text, text); Type: FUNCTION; Schema: data_warehouse; Owner: postgres
--

CREATE FUNCTION data_warehouse.set_active_model_version(p_model_id text, p_version text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Deactivate all versions of this model
    UPDATE data_warehouse.ml_model_weights
    SET is_active = FALSE
    WHERE model_id = p_model_id;

    -- Activate the specified version
    UPDATE data_warehouse.ml_model_weights
    SET is_active = TRUE
    WHERE model_id = p_model_id
      AND version = p_version;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Model version % for % not found', p_version, p_model_id;
    END IF;
END;
$$;


