-- Name: FUNCTION calculate_learning_path(p_user_id uuid, p_max_items integer); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.calculate_learning_path(p_user_id uuid, p_max_items integer) IS 'Calcula ruta de aprendizaje personalizada basada en progreso del usuario';


--
-- Name: can_teacher_access_content(uuid, uuid); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.can_teacher_access_content(p_content_id uuid, p_teacher_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_content RECORD;
BEGIN
    SELECT * INTO v_content
    FROM educational_content.teacher_contents
    WHERE id = p_content_id
      AND is_active = TRUE;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    -- Owner always has access
    IF v_content.teacher_id = p_teacher_id THEN
        RETURN TRUE;
    END IF;

    -- Check visibility
    IF v_content.visibility = 'public' THEN
        RETURN TRUE;
    END IF;

    IF v_content.visibility = 'school' OR v_content.visibility = 'classroom' THEN
        -- Check if teacher is in same tenant
        IF EXISTS (
            SELECT 1 FROM auth_management.profiles
            WHERE id = p_teacher_id
              AND tenant_id = v_content.tenant_id
        ) THEN
            RETURN TRUE;
        END IF;
    END IF;

    -- Check if explicitly shared
    IF v_content.shared_with_teachers @> to_jsonb(p_teacher_id::text) THEN
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$$;


