--
-- Name: check_rank_promotion(uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.check_rank_promotion(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_current_rank gamification_system.maya_rank;
    v_total_xp BIGINT;
    v_next_rank gamification_system.maya_rank;
    v_next_rank_min_xp BIGINT;
    v_promoted BOOLEAN := false;
BEGIN
    -- Obtener datos actuales del usuario
    SELECT current_rank, total_xp
    INTO v_current_rank, v_total_xp
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id
    FOR UPDATE; -- Lock para evitar race conditions

    -- Si no existe usuario, salir
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    -- Verificar si hay un siguiente rango disponible
    SELECT mr.next_rank, next_mr.min_xp_required
    INTO v_next_rank, v_next_rank_min_xp
    FROM gamification_system.maya_ranks mr
    LEFT JOIN gamification_system.maya_ranks next_mr
        ON next_mr.rank_name = mr.next_rank
    WHERE mr.rank_name = v_current_rank
      AND mr.is_active = true;

    -- Si no hay siguiente rango (ya está en máximo), no promocionar
    IF v_next_rank IS NULL THEN
        RETURN false;
    END IF;

    -- Verificar si el usuario tiene suficiente XP para el siguiente rango
    IF v_total_xp >= v_next_rank_min_xp THEN
        -- Promover al siguiente rango
        PERFORM gamification_system.promote_to_next_rank(p_user_id, v_next_rank);
        v_promoted := true;
    END IF;

    RETURN v_promoted;
END;
$$;


ALTER FUNCTION gamification_system.check_rank_promotion(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION check_rank_promotion(p_user_id uuid); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.check_rank_promotion(p_user_id uuid) IS 'Verifica si un usuario califica para promoción de rango según su total_xp actual.
Lee configuración dinámica desde maya_ranks table (next_rank y min_xp_required).
Retorna true si el usuario fue promovido, false en caso contrario.
Se ejecuta automáticamente mediante trigger después de actualizar total_xp.';


--
-- Name: claim_achievement_reward(uuid, uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.claim_achievement_reward(p_user_id uuid, p_achievement_id uuid) RETURNS TABLE(success boolean, xp_granted integer, coins_granted integer, message character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_achievement RECORD;
    v_achievement RECORD;
    v_already_claimed BOOLEAN;
    v_current_balance INTEGER;
    v_new_balance INTEGER;
BEGIN
    -- Verificar que el usuario tiene el logro
    SELECT * INTO v_user_achievement
    FROM gamification_system.user_achievements
    WHERE user_id = p_user_id
    AND achievement_id = p_achievement_id;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 0, 0, 'Usuario no tiene este logro'::VARCHAR;
        RETURN;
    END IF;

    -- Verificar si ya fue reclamado
    -- CORR-P1-001: Cambiado de reward_claimed_at (no existe) a rewards_claimed (BOOLEAN)
    v_already_claimed := v_user_achievement.rewards_claimed = TRUE;

    IF v_already_claimed THEN
        RETURN QUERY SELECT false, 0, 0, 'Recompensa ya fue reclamada'::VARCHAR;
        RETURN;
    END IF;

    -- Obtener datos del logro
    SELECT * INTO v_achievement
    FROM gamification_system.achievements
    WHERE id = p_achievement_id;

    IF NOT FOUND THEN
        RETURN QUERY SELECT false, 0, 0, 'Logro no encontrado'::VARCHAR;
        RETURN;
    END IF;

    -- Marcar recompensa como reclamada
    -- CORR-P1-002: Cambiado de reward_claimed_at (no existe) a rewards_claimed (BOOLEAN)
    UPDATE gamification_system.user_achievements
    SET rewards_claimed = TRUE
    WHERE user_id = p_user_id
    AND achievement_id = p_achievement_id;

    -- Obtener balance actual ANTES de actualizar (con row lock)
    SELECT ml_coins INTO v_current_balance
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id
    FOR UPDATE;

    -- Calcular nuevo balance
    v_new_balance := COALESCE(v_current_balance, 0) + v_achievement.ml_coins_reward;

    -- Otorgar recompensas
    -- CORR-P1-003: Cambiado xp_reward (no existe) a rewards->>'xp' con fallback a points_value
    UPDATE gamification_system.user_stats
    SET
        total_xp = total_xp + COALESCE((v_achievement.rewards->>'xp')::INTEGER, v_achievement.points_value, 0),
        ml_coins = v_new_balance,
        updated_at = NOW()
    WHERE user_id = p_user_id;

    -- Registrar transacción de coins si aplica
    IF v_achievement.ml_coins_reward > 0 THEN
        INSERT INTO gamification_system.ml_coins_transactions (
            user_id,
            amount,
            balance_before,
            balance_after,
            transaction_type,
            description
        ) VALUES (
            p_user_id,
            v_achievement.ml_coins_reward,
            v_current_balance,
            v_new_balance,
            'earned_achievement'::gamification_system.transaction_type,
            'Recompensa reclamada: ' || v_achievement.name
        );
    END IF;

    -- CORR-P1-004: Usar COALESCE para xp también en el retorno
    RETURN QUERY SELECT
        true,
        COALESCE((v_achievement.rewards->>'xp')::INTEGER, v_achievement.points_value, 0),
        v_achievement.ml_coins_reward,
        'Recompensa reclamada exitosamente'::VARCHAR;
END;
$$;


