--
-- Name: FUNCTION fn_on_achievement_unlocked(); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.fn_on_achievement_unlocked() IS 'Función trigger para procesar desbloqueo de achievements: otorgar XP, ML Coins, y crear notificación.';


--
-- Name: get_rank_benefits(gamification_system.maya_rank); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.get_rank_benefits(p_rank gamification_system.maya_rank) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_perks JSONB;
BEGIN
    -- Obtener perks desde maya_ranks table
    SELECT perks
    INTO v_perks
    FROM gamification_system.maya_ranks
    WHERE rank_name = p_rank
      AND is_active = true;

    -- Si no se encuentra, retornar array vacío
    IF NOT FOUND OR v_perks IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    RETURN v_perks;
END;
$$;


