--
-- Name: get_user_comodines(uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.get_user_comodines(p_user_id uuid) RETURNS TABLE(comodin_id uuid, comodin_name character varying, comodin_type character varying, category character varying, quantity integer, effect_description text, acquired_at timestamp without time zone, expires_at timestamp without time zone)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        si.id,
        si.name,
        si.item_type::VARCHAR,
        si.category::VARCHAR,
        ui.quantity,
        si.description,
        ui.acquired_at,
        ui.expires_at
    FROM gamification_system.user_inventory ui
    JOIN gamification_system.store_items si ON si.id = ui.item_id
    WHERE ui.user_id = p_user_id
    AND si.item_type = 'CONSUMABLE'
    AND ui.quantity > 0
    AND (ui.expires_at IS NULL OR ui.expires_at > NOW())
    ORDER BY
        CASE si.category
            WHEN 'XP_BOOST' THEN 1
            WHEN 'COIN_MULTIPLIER' THEN 2
            WHEN 'SKIP_MISSION' THEN 3
            ELSE 4
        END,
        ui.acquired_at DESC;
END;
$$;


