--
-- Name: get_user_inventory_summary(uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.get_user_inventory_summary(p_user_id uuid) RETURNS TABLE(total_items integer, total_value_coins integer, items_by_category jsonb, consumables_count integer, cosmetics_count integer, boosts_count integer, recent_acquisitions jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::INTEGER AS total_items,
        COALESCE(SUM(si.price * up.quantity), 0)::INTEGER AS total_value_coins,
        COALESCE(
            jsonb_object_agg(si.category, cat_count.cnt),
            '{}'::jsonb
        ) AS items_by_category,
        COUNT(*) FILTER (WHERE si.is_consumable = true)::INTEGER AS consumables_count,
        COUNT(*) FILTER (WHERE si.is_consumable = false AND si.category IN ('cosmetics', 'profile'))::INTEGER AS cosmetics_count,
        COUNT(*) FILTER (WHERE si.is_consumable = true AND si.effect_data->>'type' IN ('xp_boost', 'coins_boost'))::INTEGER AS boosts_count,
        (
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'item_name', si2.name,
                    'quantity', up2.quantity,
                    'purchased_at', up2.purchased_at
                )
            ), '[]'::jsonb)
            FROM gamification_system.user_purchases up2
            JOIN gamification_system.shop_items si2 ON si2.id = up2.item_id
            WHERE up2.user_id = p_user_id
              AND up2.status = 'completed'
            ORDER BY up2.purchased_at DESC
            LIMIT 5
        ) AS recent_acquisitions
    FROM gamification_system.user_purchases up
    JOIN gamification_system.shop_items si ON si.id = up.item_id
    LEFT JOIN LATERAL (
        SELECT si_inner.category, COUNT(*)::INTEGER AS cnt
        FROM gamification_system.user_purchases up_inner
        JOIN gamification_system.shop_items si_inner ON si_inner.id = up_inner.item_id
        WHERE up_inner.user_id = p_user_id AND up_inner.status = 'completed'
        GROUP BY si_inner.category
    ) cat_count ON cat_count.category = si.category
    WHERE up.user_id = p_user_id
      AND up.status = 'completed'
    GROUP BY up.user_id;
END;
$$;


ALTER FUNCTION gamification_system.get_user_inventory_summary(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION get_user_inventory_summary(p_user_id uuid); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.get_user_inventory_summary(p_user_id uuid) IS 'Obtiene resumen completo del inventario del usuario con estadísticas (v2.0 - tablas corregidas)';


--
-- Name: get_user_rank_progress(uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.get_user_rank_progress(p_user_id uuid) RETURNS TABLE(current_rank gamification_system.maya_rank, current_xp bigint, next_rank gamification_system.maya_rank, next_rank_xp bigint, xp_needed bigint, progress_percentage numeric, modules_completed integer, missions_required integer)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_user_stats RECORD;
    v_current_rank_xp BIGINT;
    v_next_rank RECORD;
BEGIN
    -- Obtener estadísticas del usuario
    -- FIX 2026-01-04: Agregar is_current = true para evitar duplicados
    SELECT us.*, ur.current_rank
    INTO v_user_stats
    FROM gamification_system.user_stats us
    JOIN gamification_system.user_ranks ur ON ur.user_id = us.user_id AND ur.is_current = true
    WHERE us.user_id = p_user_id;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Obtener XP del rango actual
    SELECT min_xp_required INTO v_current_rank_xp
    FROM gamification_system.maya_ranks
    WHERE name = v_user_stats.current_rank::VARCHAR;

    -- Obtener siguiente rango
    SELECT mr.name::gamification_system.maya_rank, mr.min_xp_required, mr.missions_required
    INTO v_next_rank
    FROM gamification_system.maya_ranks mr
    WHERE mr.min_xp_required > v_current_rank_xp
    ORDER BY mr.min_xp_required ASC
    LIMIT 1;

    IF NOT FOUND THEN
        -- Usuario está en rango máximo
        RETURN QUERY SELECT
            v_user_stats.current_rank,
            v_user_stats.total_xp,
            v_user_stats.current_rank,
            v_user_stats.total_xp,
            0::BIGINT,
            100.00::NUMERIC,
            v_user_stats.modules_completed,
            0::INTEGER;
    ELSE
        RETURN QUERY SELECT
            v_user_stats.current_rank,
            v_user_stats.total_xp,
            v_next_rank.name,
            v_next_rank.min_xp_required,
            GREATEST(0, v_next_rank.min_xp_required - v_user_stats.total_xp),
            LEAST(100, (v_user_stats.total_xp - v_current_rank_xp)::NUMERIC /
                  NULLIF(v_next_rank.min_xp_required - v_current_rank_xp, 0) * 100),
            v_user_stats.modules_completed,
            v_next_rank.missions_required;
    END IF;
END;
$$;


