--
-- Name: process_xp_update(); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.process_xp_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_new_level INTEGER;
    v_xp_gained INTEGER;
    v_old_xp INTEGER;
BEGIN
    -- =======================================================================
    -- FILTRO RAPIDO: Solo ejecutar si total_xp cambio
    -- =======================================================================
    v_old_xp := COALESCE(OLD.total_xp, 0);

    IF NEW.total_xp IS NOT DISTINCT FROM v_old_xp THEN
        RETURN NEW;
    END IF;

    -- =======================================================================
    -- PASO 1: Recalcular nivel (CONSOLIDACION de trigger 4A)
    -- =======================================================================
    -- Usa la funcion existente calculate_level_from_xp
    v_new_level := gamification_system.calculate_level_from_xp(NEW.total_xp);

    -- Solo actualizar si el nivel realmente cambio
    IF v_new_level IS DISTINCT FROM NEW.level THEN
        NEW.level := v_new_level;

        -- Log para debugging
        RAISE NOTICE 'User % level changed: % -> % (XP: %)',
            NEW.user_id, OLD.level, v_new_level, NEW.total_xp;
    END IF;

    -- =======================================================================
    -- PASO 2: Actualizar misiones de XP (CONSOLIDACION de trigger 4B)
    -- =======================================================================
    v_xp_gained := NEW.total_xp - v_old_xp;

    -- Solo actualizar misiones si ganamos XP (no si perdimos)
    IF v_xp_gained > 0 THEN
        -- Usa la funcion unificada de misiones existente
        PERFORM gamilit.update_mission_progress(
            NEW.user_id,
            'earn_xp',
            v_xp_gained
        );

        RAISE NOTICE 'User % earned % XP, updated earn_xp missions',
            NEW.user_id, v_xp_gained;
    END IF;

    -- =======================================================================
    -- PASO 3: Actualizar timestamp (evita trigger cascade updated_at)
    -- =======================================================================
    NEW.updated_at := gamilit.now_mexico();

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no bloquear el update de user_stats
        RAISE WARNING 'Error en process_xp_update para usuario %: %',
            NEW.user_id, SQLERRM;
        -- Aun asi, intentar al menos actualizar el nivel
        BEGIN
            v_new_level := gamification_system.calculate_level_from_xp(NEW.total_xp);
            IF v_new_level IS DISTINCT FROM NEW.level THEN
                NEW.level := v_new_level;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL; -- Ignorar errores secundarios
        END;
        RETURN NEW;
END;
$$;


ALTER FUNCTION gamification_system.process_xp_update() OWNER TO postgres;

--
-- Name: FUNCTION process_xp_update(); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.process_xp_update() IS 'Trigger function CONSOLIDADA que combina recalculate_level_on_xp_change y update_missions_on_earn_xp. Ejecuta ANTES del UPDATE de user_stats para modificar level directamente. Reduce latencia de 20-35ms a 5-10ms (-70%) por actualizacion de XP. Creada: TASK-2026-02-02-IMPLEMENTAR-OPTIMIZACION-TRIGGERS';


--
-- Name: promote_to_next_rank(uuid, gamification_system.maya_rank); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.promote_to_next_rank(p_user_id uuid, p_new_rank gamification_system.maya_rank) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_old_rank gamification_system.maya_rank;
    v_total_xp BIGINT;
    v_days_in_old_rank INTEGER;
    v_ml_coins_bonus INTEGER;
    v_achievement_id UUID;
    v_old_rank_achieved_at TIMESTAMPTZ;
    v_current_balance INTEGER;
    v_new_balance INTEGER;
BEGIN
    -- Obtener datos actuales de user_stats
    SELECT
        current_rank,
        total_xp
    INTO
        v_old_rank,
        v_total_xp
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id;

    -- Obtener fecha del rango anterior desde user_ranks
    SELECT achieved_at
    INTO v_old_rank_achieved_at
    FROM gamification_system.user_ranks
    WHERE user_id = p_user_id AND is_current = true;

    -- Si no hay registro en user_ranks, usar created_at de user_stats
    IF v_old_rank_achieved_at IS NULL THEN
        SELECT created_at INTO v_old_rank_achieved_at
        FROM gamification_system.user_stats
        WHERE user_id = p_user_id;
    END IF;

    -- Calcular días en el rango anterior
    v_days_in_old_rank := EXTRACT(DAY FROM gamilit.now_mexico() - v_old_rank_achieved_at)::INTEGER;

    -- Verificar que el usuario existe
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Usuario no encontrado: %', p_user_id;
    END IF;

    -- Obtener ML Coins bonus desde maya_ranks table (dinámico)
    SELECT ml_coins_bonus
    INTO v_ml_coins_bonus
    FROM gamification_system.maya_ranks
    WHERE rank_name = p_new_rank
      AND is_active = true;

    -- Si no se encuentra el rango, usar 0
    IF v_ml_coins_bonus IS NULL THEN
        v_ml_coins_bonus := 0;
    END IF;

    -- Obtener balance actual ANTES del cambio con row lock
    SELECT ml_coins INTO v_current_balance
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id
    FOR UPDATE;

    -- Calcular nuevo balance
    v_new_balance := COALESCE(v_current_balance, 0) + v_ml_coins_bonus;

    -- 1. Actualizar current_rank en user_stats
    -- Solo actualizar current_rank y ml_coins (no hay columnas achieved_at, previous_rank, etc.)
    UPDATE gamification_system.user_stats
    SET
        current_rank = p_new_rank,
        ml_coins = v_new_balance,
        updated_at = gamilit.now_mexico()
    WHERE user_id = p_user_id;

    -- 2. Actualizar user_ranks table con nuevo rango
    INSERT INTO gamification_system.user_ranks (
        user_id,
        current_rank,
        previous_rank,
        ml_coins_bonus,
        achieved_at,
        previous_rank_achieved_at,
        is_current
    ) VALUES (
        p_user_id,
        p_new_rank,
        v_old_rank,
        v_ml_coins_bonus,
        gamilit.now_mexico(),
        v_old_rank_achieved_at,
        true
    )
    ON CONFLICT (user_id)
    DO UPDATE SET
        previous_rank = v_old_rank,
        current_rank = p_new_rank,
        ml_coins_bonus = v_ml_coins_bonus,
        previous_rank_achieved_at = v_old_rank_achieved_at,
        achieved_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico();

    -- 3. Registrar transacción de ML Coins
    INSERT INTO gamification_system.ml_coins_transactions (
        user_id,
        amount,
        balance_before,
        balance_after,
        transaction_type,
        description,
        metadata
    ) VALUES (
        p_user_id,
        v_ml_coins_bonus,
        v_current_balance,
        v_new_balance,
        'earned_rank'::gamification_system.transaction_type,
        'Ascendiste al rango ' || p_new_rank::TEXT,
        jsonb_build_object(
            'old_rank', v_old_rank::TEXT,
            'new_rank', p_new_rank::TEXT,
            'xp_at_promotion', v_total_xp
        )
    );

    -- 4. TODO: Crear achievement rank_promotion (requiere tabla user_achievements)
    -- 5. TODO: Registrar en rank_history (requiere crear tabla)
    -- 6. TODO: Crear notificación rank_up (requiere tabla notifications)

    -- Log de auditoría
    RAISE NOTICE 'Promoción exitosa: Usuario % promovido de % a % (+% ML Coins)',
        p_user_id, v_old_rank, p_new_rank, v_ml_coins_bonus;

END;
$$;


