-- Name: FUNCTION set_profile_defaults(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.set_profile_defaults() IS 'Establece valores por defecto para nuevos usuarios (is_active=true, email_verified=true)';


--
-- Name: trigger_missions_on_complete_modules(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.trigger_missions_on_complete_modules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Solo procesar si se completo un modulo nuevo
    IF NEW.modules_completed > COALESCE(OLD.modules_completed, 0) THEN
        PERFORM gamilit.update_mission_progress(NEW.user_id, 'complete_modules', 1);
    END IF;
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Error in trigger_missions_on_complete_modules: %', SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION gamilit.trigger_missions_on_complete_modules() OWNER TO postgres;

--
-- Name: FUNCTION trigger_missions_on_complete_modules(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.trigger_missions_on_complete_modules() IS 'Trigger wrapper que actualiza misiones al completar un modulo.
Llama a update_mission_progress con type=complete_modules, increment=1.
Tabla: gamification_system.user_stats
Evento: AFTER UPDATE (when modules_completed changes)';


