--
-- Name: update_mission_progress(uuid, text, integer); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.update_mission_progress(p_user_id uuid, p_objective_type text, p_increment_value integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_mission RECORD;
    v_objectives JSONB;
    v_new_objectives JSONB;
    v_objective JSONB;
    v_new_current INTEGER;
    v_total_progress FLOAT;
    v_obj_count INTEGER;
    v_obj_progress FLOAT;
    v_i INTEGER;
    v_all_completed BOOLEAN;
BEGIN
    -- Validar parametros
    IF p_user_id IS NULL OR p_objective_type IS NULL OR p_objective_type = '' THEN
        RETURN;
    END IF;

    -- Buscar misiones activas o en progreso del usuario con objetivo del tipo especificado
    FOR v_mission IN
        SELECT id, objectives, status
        FROM gamification_system.missions
        WHERE user_id = p_user_id
          AND status IN ('active', 'in_progress')
          AND end_date > gamilit.now_mexico()
          AND objectives @> format('[{"type": "%s"}]', p_objective_type)::jsonb
    LOOP
        BEGIN
            v_objectives := v_mission.objectives;
            v_new_objectives := '[]'::jsonb;
            v_total_progress := 0;
            v_obj_count := jsonb_array_length(v_objectives);
            v_all_completed := TRUE;

            -- Iterar sobre cada objetivo
            FOR v_i IN 0..v_obj_count-1 LOOP
                v_objective := v_objectives->v_i;

                -- Si es objetivo del tipo especificado, incrementar
                IF v_objective->>'type' = p_objective_type THEN
                    v_new_current := LEAST(
                        COALESCE((v_objective->>'current')::INTEGER, 0) + p_increment_value,
                        (v_objective->>'target')::INTEGER
                    );
                    v_objective := jsonb_set(v_objective, '{current}', to_jsonb(v_new_current));

                    -- Verificar si este objetivo esta completo
                    IF v_new_current < (v_objective->>'target')::INTEGER THEN
                        v_all_completed := FALSE;
                    END IF;
                ELSE
                    -- Verificar si otros objetivos estan completos
                    IF COALESCE((v_objective->>'current')::INTEGER, 0) < (v_objective->>'target')::INTEGER THEN
                        v_all_completed := FALSE;
                    END IF;
                END IF;

                -- Calcular progreso de este objetivo (0-100%)
                v_obj_progress := (
                    COALESCE((v_objective->>'current')::FLOAT, 0) /
                    NULLIF((v_objective->>'target')::FLOAT, 0)
                ) * 100;
                v_total_progress := v_total_progress + COALESCE(v_obj_progress, 0);

                -- Agregar objetivo actualizado al array
                v_new_objectives := v_new_objectives || jsonb_build_array(v_objective);
            END LOOP;

            -- Calcular progreso total de la mision (promedio de objetivos)
            v_total_progress := LEAST(v_total_progress / NULLIF(v_obj_count, 0), 100);

            -- Actualizar la mision
            UPDATE gamification_system.missions
            SET
                objectives = v_new_objectives,
                progress = ROUND(COALESCE(v_total_progress, 0)::NUMERIC, 2),
                status = CASE
                    WHEN v_all_completed AND v_total_progress >= 100 THEN 'completed'
                    WHEN v_total_progress > 0 AND status = 'active' THEN 'in_progress'
                    ELSE status
                END,
                completed_at = CASE
                    WHEN v_all_completed AND v_total_progress >= 100 AND completed_at IS NULL
                    THEN gamilit.now_mexico()
                    ELSE completed_at
                END,
                updated_at = gamilit.now_mexico()
            WHERE id = v_mission.id;

            RAISE NOTICE 'Mission % updated: type=%, increment=%, progress=%',
                v_mission.id, p_objective_type, p_increment_value, v_total_progress;

        EXCEPTION
            WHEN OTHERS THEN
                -- Log error pero continuar con otras misiones
                RAISE WARNING 'Error updating mission % for user % (type=%): %',
                    v_mission.id, p_user_id, p_objective_type, SQLERRM;
        END;
    END LOOP;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error global pero no propagar
        RAISE WARNING 'Error in update_mission_progress for user % (type=%): %',
            p_user_id, p_objective_type, SQLERRM;
END;
$$;


ALTER FUNCTION gamilit.update_mission_progress(p_user_id uuid, p_objective_type text, p_increment_value integer) OWNER TO postgres;

--
-- Name: FUNCTION update_mission_progress(p_user_id uuid, p_objective_type text, p_increment_value integer); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.update_mission_progress(p_user_id uuid, p_objective_type text, p_increment_value integer) IS 'Funcion UNIFICADA para actualizar el progreso de misiones.
Reemplaza 8 funciones duplicadas (update_missions_on_*).
Parametros:
  - p_user_id: UUID del usuario
  - p_objective_type: Tipo de objetivo a actualizar (complete_exercises, earn_xp, etc.)
  - p_increment_value: Valor a incrementar (default 1)
Tipos de objetivo soportados:
  - complete_exercises: Completar ejercicios
  - earn_xp: Ganar XP
  - correct_streak: Racha de ejercicios correctos
  - daily_streak: Racha de dias consecutivos
  - use_comodines: Usar comodines
  - perfect_scores: Obtener puntajes perfectos
  - complete_modules: Completar modulos
  - explore_modules: Explorar modulos nuevos';


--
-- Name: update_module_progress_on_exercise_complete(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.update_module_progress_on_exercise_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_module_id UUID;
    v_total_exercises INTEGER;
    v_completed_exercises INTEGER;
    v_progress_percentage NUMERIC;
    v_new_status progress_tracking.progress_status;
    v_is_first_correct_for_exercise BOOLEAN;
    v_current_status progress_tracking.progress_status;
BEGIN
    -- Solo procesar si el ejercicio fue correcto
    IF NOT (NEW.is_correct = true OR NEW.score >= 60) THEN
        RETURN NEW;
    END IF;

    -- Obtener el module_id del ejercicio
    SELECT module_id INTO v_module_id
    FROM educational_content.exercises
    WHERE id = NEW.exercise_id;

    IF v_module_id IS NULL THEN
        RAISE WARNING 'Ejercicio % no tiene module_id asociado', NEW.exercise_id;
        RETURN NEW;
    END IF;

    -- Verificar si es el primer intento correcto para ESTE ejercicio especifico
    SELECT NOT EXISTS (
        SELECT 1 FROM progress_tracking.exercise_attempts
        WHERE user_id = NEW.user_id
          AND exercise_id = NEW.exercise_id
          AND is_correct = true
          AND id != NEW.id
    ) INTO v_is_first_correct_for_exercise;

    -- Si no es el primer acierto para este ejercicio, solo actualizar timestamps
    IF NOT v_is_first_correct_for_exercise THEN
        UPDATE progress_tracking.module_progress
        SET last_accessed_at = gamilit.now_mexico(),
            updated_at = gamilit.now_mexico()
        WHERE user_id = NEW.user_id AND module_id = v_module_id;
        RETURN NEW;
    END IF;

    -- Contar total de ejercicios activos en el modulo
    SELECT COUNT(*)
    INTO v_total_exercises
    FROM educational_content.exercises
    WHERE module_id = v_module_id AND is_active = true;

    -- Contar ejercicios correctos UNICOS del usuario en este modulo
    SELECT COUNT(DISTINCT ea.exercise_id)
    INTO v_completed_exercises
    FROM progress_tracking.exercise_attempts ea
    JOIN educational_content.exercises e ON e.id = ea.exercise_id
    WHERE ea.user_id = NEW.user_id
      AND e.module_id = v_module_id
      AND ea.is_correct = true;

    -- Calcular porcentaje de progreso
    IF v_total_exercises > 0 THEN
        v_progress_percentage := ROUND((v_completed_exercises::NUMERIC / v_total_exercises::NUMERIC) * 100, 2);
    ELSE
        v_progress_percentage := 0;
    END IF;

    -- Determinar nuevo status
    IF v_progress_percentage >= 100 THEN
        v_new_status := 'completed';
    ELSIF v_progress_percentage > 0 THEN
        v_new_status := 'in_progress';
    ELSE
        v_new_status := 'not_started';
    END IF;

    -- Obtener status actual
    SELECT status INTO v_current_status
    FROM progress_tracking.module_progress
    WHERE user_id = NEW.user_id AND module_id = v_module_id;

    -- Actualizar module_progress
    UPDATE progress_tracking.module_progress
    SET
        completed_exercises = v_completed_exercises,
        total_exercises = v_total_exercises,
        progress_percentage = v_progress_percentage,
        -- FEATURE M3-M5 2026-01-08: Actualizar graded tracking (ejercicios auto-calificados)
        graded_exercises = v_completed_exercises,
        graded_progress_percentage = v_progress_percentage,
        status = v_new_status,
        total_xp_earned = total_xp_earned + COALESCE(NEW.xp_earned, 0),
        total_ml_coins_earned = total_ml_coins_earned + COALESCE(NEW.ml_coins_earned, 0),
        -- Establecer started_at solo si es el primer ejercicio
        started_at = CASE
            WHEN started_at IS NULL THEN gamilit.now_mexico()
            ELSE started_at
        END,
        -- Establecer completed_at cuando se completa el modulo
        completed_at = CASE
            WHEN v_new_status = 'completed' AND (completed_at IS NULL OR v_current_status != 'completed')
            THEN gamilit.now_mexico()
            ELSE completed_at
        END,
        last_accessed_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico()
    WHERE user_id = NEW.user_id AND module_id = v_module_id;

    -- Si no existe el registro de progreso, crearlo
    IF NOT FOUND THEN
        INSERT INTO progress_tracking.module_progress (
            user_id,
            module_id,
            status,
            progress_percentage,
            completed_exercises,
            total_exercises,
            -- FEATURE M3-M5 2026-01-08: Columnas de graded tracking
            graded_exercises,
            graded_progress_percentage,
            total_xp_earned,
            total_ml_coins_earned,
            started_at,
            last_accessed_at
        ) VALUES (
            NEW.user_id,
            v_module_id,
            v_new_status,
            v_progress_percentage,
            v_completed_exercises,
            v_total_exercises,
            -- FEATURE M3-M5 2026-01-08: Valores para graded tracking
            v_completed_exercises,
            v_progress_percentage,
            COALESCE(NEW.xp_earned, 0),
            COALESCE(NEW.ml_coins_earned, 0),
            gamilit.now_mexico(),
            gamilit.now_mexico()
        );
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no bloquear el insert del attempt
        RAISE WARNING 'Error al actualizar progreso de modulo para usuario %: %', NEW.user_id, SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION gamilit.update_module_progress_on_exercise_complete() OWNER TO postgres;

--
-- Name: FUNCTION update_module_progress_on_exercise_complete(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.update_module_progress_on_exercise_complete() IS 'Trigger function que actualiza el progreso del modulo al completar un ejercicio correctamente. Calcula porcentaje de avance, actualiza contadores y determina status (not_started/in_progress/completed). Solo cuenta un ejercicio una vez aunque tenga multiples intentos correctos.';


--
-- Name: update_module_progress_on_submission_graded(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.update_module_progress_on_submission_graded() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_module_id UUID;
    v_total_exercises INTEGER;
    v_completed_exercises INTEGER;
    v_progress_percentage NUMERIC;
    v_new_status progress_tracking.progress_status;
    v_is_first_approved_for_exercise BOOLEAN;
    v_current_status progress_tracking.progress_status;
BEGIN
    -- Solo procesar si el submission fue aprobado (score >= 60)
    IF NEW.score < 60 THEN
        RETURN NEW;
    END IF;

    -- Obtener el module_id del ejercicio
    SELECT module_id INTO v_module_id
    FROM educational_content.exercises
    WHERE id = NEW.exercise_id;

    IF v_module_id IS NULL THEN
        RAISE WARNING 'Ejercicio % no tiene module_id asociado', NEW.exercise_id;
        RETURN NEW;
    END IF;

    -- Verificar si es el primer submission aprobado para ESTE ejercicio especifico
    -- Cuenta submissions con score >= 60 del mismo usuario en el mismo ejercicio
    SELECT NOT EXISTS (
        SELECT 1 FROM progress_tracking.exercise_submissions
        WHERE user_id = NEW.user_id
          AND exercise_id = NEW.exercise_id
          AND score >= 60
          AND status IN ('graded', 'reviewed')
          AND id != NEW.id
    ) INTO v_is_first_approved_for_exercise;

    -- Si no es el primer aprobado para este ejercicio, solo actualizar timestamps
    IF NOT v_is_first_approved_for_exercise THEN
        UPDATE progress_tracking.module_progress
        SET last_accessed_at = gamilit.now_mexico(),
            updated_at = gamilit.now_mexico()
        WHERE user_id = NEW.user_id AND module_id = v_module_id;
        RETURN NEW;
    END IF;

    -- Contar total de ejercicios activos en el modulo
    SELECT COUNT(*)
    INTO v_total_exercises
    FROM educational_content.exercises
    WHERE module_id = v_module_id AND is_active = true;

    -- Contar ejercicios aprobados UNICOS del usuario en este modulo
    -- Incluye tanto exercise_attempts (is_correct=true) como exercise_submissions (score>=60)
    SELECT COUNT(DISTINCT exercise_id)
    INTO v_completed_exercises
    FROM (
        -- Ejercicios auto-calificados correctos (attempts)
        SELECT ea.exercise_id
        FROM progress_tracking.exercise_attempts ea
        JOIN educational_content.exercises e ON e.id = ea.exercise_id
        WHERE ea.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND ea.is_correct = true

        UNION

        -- Ejercicios con revision manual aprobados (submissions)
        SELECT es.exercise_id
        FROM progress_tracking.exercise_submissions es
        JOIN educational_content.exercises e ON e.id = es.exercise_id
        WHERE es.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND es.score >= 60
          AND es.status IN ('graded', 'reviewed')
    ) completed;

    -- Calcular porcentaje de progreso
    IF v_total_exercises > 0 THEN
        v_progress_percentage := ROUND((v_completed_exercises::NUMERIC / v_total_exercises::NUMERIC) * 100, 2);
    ELSE
        v_progress_percentage := 0;
    END IF;

    -- Determinar nuevo status
    IF v_progress_percentage >= 100 THEN
        v_new_status := 'completed';
    ELSIF v_progress_percentage > 0 THEN
        v_new_status := 'in_progress';
    ELSE
        v_new_status := 'not_started';
    END IF;

    -- Obtener status actual
    SELECT status INTO v_current_status
    FROM progress_tracking.module_progress
    WHERE user_id = NEW.user_id AND module_id = v_module_id;

    -- Actualizar module_progress
    UPDATE progress_tracking.module_progress
    SET
        completed_exercises = v_completed_exercises,
        total_exercises = v_total_exercises,
        progress_percentage = v_progress_percentage,
        -- FEATURE M3-M5 2026-01-08: Actualizar graded tracking
        graded_exercises = v_completed_exercises,
        graded_progress_percentage = v_progress_percentage,
        status = v_new_status,
        total_xp_earned = total_xp_earned + COALESCE(NEW.xp_earned, 0),
        total_ml_coins_earned = total_ml_coins_earned + COALESCE(NEW.ml_coins_earned, 0),
        -- Establecer started_at solo si es el primer ejercicio
        started_at = CASE
            WHEN started_at IS NULL THEN gamilit.now_mexico()
            ELSE started_at
        END,
        -- Establecer completed_at cuando se completa el modulo
        completed_at = CASE
            WHEN v_new_status = 'completed' AND (completed_at IS NULL OR v_current_status != 'completed')
            THEN gamilit.now_mexico()
            ELSE completed_at
        END,
        last_accessed_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico()
    WHERE user_id = NEW.user_id AND module_id = v_module_id;

    -- Si no existe el registro de progreso, crearlo
    IF NOT FOUND THEN
        INSERT INTO progress_tracking.module_progress (
            user_id,
            module_id,
            status,
            progress_percentage,
            completed_exercises,
            total_exercises,
            -- FEATURE M3-M5 2026-01-08: Columnas de graded tracking
            graded_exercises,
            graded_progress_percentage,
            total_xp_earned,
            total_ml_coins_earned,
            started_at,
            last_accessed_at
        ) VALUES (
            NEW.user_id,
            v_module_id,
            v_new_status,
            v_progress_percentage,
            v_completed_exercises,
            v_total_exercises,
            -- FEATURE M3-M5 2026-01-08: Valores para graded tracking
            v_completed_exercises,
            v_progress_percentage,
            COALESCE(NEW.xp_earned, 0),
            COALESCE(NEW.ml_coins_earned, 0),
            gamilit.now_mexico(),
            gamilit.now_mexico()
        );
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no bloquear el update del submission
        RAISE WARNING 'Error al actualizar progreso de modulo para usuario % en submission %: %',
            NEW.user_id, NEW.id, SQLERRM;
        RETURN NEW;
END;
$$;


