COMMENT ON FUNCTION notifications.send_notification(p_user_id uuid, p_type character varying, p_title character varying, p_message text, p_data jsonb, p_priority character varying) IS 'Crea una notificación respetando las preferencias del usuario y la encola para envío';


--
-- Name: calculate_module_progress(uuid, uuid); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.calculate_module_progress(p_user_id uuid, p_module_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_total_exercises INTEGER;
    v_completed_exercises INTEGER;
    v_progress NUMERIC;
BEGIN
    -- Count total exercises in module
    SELECT COUNT(*)
    INTO v_total_exercises
    FROM educational_content.exercises
    WHERE module_id = p_module_id AND is_active = true;

    -- Count completed exercises by user
    SELECT COUNT(DISTINCT ea.exercise_id)
    INTO v_completed_exercises
    FROM progress_tracking.exercise_attempts ea
    JOIN educational_content.exercises e ON e.id = ea.exercise_id
    WHERE ea.user_id = p_user_id
      AND e.module_id = p_module_id
      AND ea.is_correct = true;

    -- Calculate percentage
    IF v_total_exercises = 0 THEN
        RETURN 0;
    END IF;

    v_progress := (v_completed_exercises::numeric / v_total_exercises::numeric) * 100;
    RETURN ROUND(v_progress, 2);
END;
$$;


