-- Name: FUNCTION calculate_module_progress(p_user_id uuid, p_module_id uuid); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.calculate_module_progress(p_user_id uuid, p_module_id uuid) IS 'Calcula el porcentaje de progreso en un módulo';


--
-- Name: check_difficulty_promotion_eligibility(uuid, educational_content.difficulty_level); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.check_difficulty_promotion_eligibility(p_user_id uuid, p_difficulty_level educational_content.difficulty_level) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_progress RECORD;
    v_criteria RECORD;
    v_time_ratio NUMERIC;
    v_avg_time_for_level NUMERIC;
BEGIN
    -- Obtener progreso del usuario
    SELECT *
    INTO v_user_progress
    FROM progress_tracking.user_difficulty_progress
    WHERE user_id = p_user_id
      AND difficulty_level = p_difficulty_level;

    -- Si no tiene intentos, no es elegible
    IF NOT FOUND OR v_user_progress.exercises_attempted < 1 THEN
        RETURN FALSE;
    END IF;

    -- Obtener criterios del nivel
    SELECT *
    INTO v_criteria
    FROM educational_content.difficulty_criteria
    WHERE level = p_difficulty_level;

    -- Verificar cantidad mínima de ejercicios
    IF v_user_progress.exercises_completed < v_criteria.promotion_min_exercises THEN
        RETURN FALSE;
    END IF;

    -- Verificar tasa de éxito
    IF v_user_progress.success_rate < v_criteria.promotion_success_rate THEN
        RETURN FALSE;
    END IF;

    -- Verificar tiempo promedio
    -- Calcular el tiempo promedio esperado para este nivel
    SELECT AVG(udp.avg_time_per_exercise)
    INTO v_avg_time_for_level
    FROM progress_tracking.user_difficulty_progress udp
    WHERE udp.difficulty_level = p_difficulty_level
      AND udp.exercises_completed >= 10;

    -- Si hay datos suficientes, verificar que el usuario no toma excesivo tiempo
    IF v_avg_time_for_level IS NOT NULL AND v_avg_time_for_level > 0 THEN
        v_time_ratio := v_user_progress.avg_time_per_exercise / v_avg_time_for_level;

        IF v_time_ratio > v_criteria.promotion_time_threshold THEN
            RETURN FALSE;
        END IF;
    END IF;

    -- Si pasa todos los criterios, es elegible
    RETURN TRUE;
END;
$$;


ALTER FUNCTION progress_tracking.check_difficulty_promotion_eligibility(p_user_id uuid, p_difficulty_level educational_content.difficulty_level) OWNER TO postgres;

--
-- Name: FUNCTION check_difficulty_promotion_eligibility(p_user_id uuid, p_difficulty_level educational_content.difficulty_level); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.check_difficulty_promotion_eligibility(p_user_id uuid, p_difficulty_level educational_content.difficulty_level) IS 'Verifica si un usuario cumple los criterios para promoción al siguiente nivel de dificultad CEFR.
Criterios evaluados: mínimo de ejercicios, tasa de éxito, y tiempo promedio vs otros usuarios.';


--
-- Name: create_manual_review_on_submission(); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.create_manual_review_on_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'progress_tracking', 'educational_content', 'social_features', 'auth_management', 'public'
    AS $$
DECLARE
    v_requires_manual BOOLEAN;
    v_teacher_id UUID;
    v_classroom_id UUID;
BEGIN
    -- =========================================================================
    -- PASO 1: Verificar si el ejercicio requiere revision manual
    -- =========================================================================
    SELECT requires_manual_grading INTO v_requires_manual
    FROM educational_content.exercises
    WHERE id = NEW.exercise_id;

    -- Si no requiere revision manual, salir sin hacer nada
    IF NOT COALESCE(v_requires_manual, FALSE) THEN
        RETURN NEW;
    END IF;

    -- =========================================================================
    -- PASO 2: Obtener el classroom activo del estudiante
    -- =========================================================================
    SELECT classroom_id INTO v_classroom_id
    FROM social_features.classroom_members
    WHERE student_id = NEW.user_id
      AND is_active = TRUE
    ORDER BY created_at DESC
    LIMIT 1;

    -- =========================================================================
    -- PASO 3: Obtener el teacher del classroom
    -- =========================================================================
    IF v_classroom_id IS NOT NULL THEN
        SELECT teacher_id INTO v_teacher_id
        FROM social_features.classrooms
        WHERE id = v_classroom_id;
    END IF;

    -- =========================================================================
    -- PASO 4: Si no hay teacher asignado, buscar admin por defecto
    -- =========================================================================
    IF v_teacher_id IS NULL THEN
        SELECT id INTO v_teacher_id
        FROM auth_management.profiles
        WHERE role IN ('admin_teacher', 'super_admin')
          AND is_active = TRUE
        ORDER BY created_at ASC
        LIMIT 1;
    END IF;

    -- =========================================================================
    -- PASO 5: Crear el ManualReview
    -- =========================================================================
    -- Usar ON CONFLICT DO NOTHING para evitar duplicados (constraint unique_submission_review)
    INSERT INTO progress_tracking.manual_reviews (
        submission_id,
        reviewer_id,
        status,
        rubric_scores,
        created_at
    ) VALUES (
        NEW.id,
        v_teacher_id,
        'pending',
        '{}'::jsonb,
        gamilit.now_mexico()
    ) ON CONFLICT (submission_id) DO NOTHING;

    -- Log para debugging (solo en desarrollo)
    RAISE NOTICE 'ManualReview created for submission % with reviewer %', NEW.id, v_teacher_id;

    RETURN NEW;

EXCEPTION WHEN OTHERS THEN
    -- =========================================================================
    -- MANEJO DE ERRORES: No bloquear el submission, solo loguear
    -- =========================================================================
    RAISE WARNING 'Error creating ManualReview for submission %: %', NEW.id, SQLERRM;

    -- Opcionalmente, insertar en tabla de errores para retry posterior
    BEGIN
        INSERT INTO audit_logging.pending_user_initialization (
            user_id,
            profile_id,
            error_message,
            error_code,
            trigger_name,
            function_name,
            status
        ) VALUES (
            NEW.user_id,
            NEW.user_id,
            SQLERRM,
            'P0-001',
            'trg_create_manual_review_on_submission',
            'progress_tracking.create_manual_review_on_submission',
            'pending'
        );
    EXCEPTION WHEN OTHERS THEN
        -- Ignorar errores al insertar en audit_logging
        NULL;
    END;

    RETURN NEW;
END;
$$;


ALTER FUNCTION progress_tracking.create_manual_review_on_submission() OWNER TO postgres;

--
-- Name: FUNCTION create_manual_review_on_submission(); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.create_manual_review_on_submission() IS 'Crea automaticamente un ManualReview cuando se inserta un ExerciseSubmission para ejercicios con requires_manual_grading=true. Asigna el teacher del classroom del estudiante, o un admin por defecto si no hay teacher asignado.';


--
-- Name: generate_student_alerts(); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.generate_student_alerts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_alerts_count INTEGER := 0;
  v_no_activity_count INTEGER := 0;
  v_low_score_count INTEGER := 0;
  v_repeated_failures_count INTEGER := 0;
BEGIN
  -- ============================================================================
  -- 1. DETECTAR ESTUDIANTES SIN ACTIVIDAD (7+ días)
  -- ============================================================================
  -- Genera alertas para estudiantes que no han tenido actividad reciente
  -- La severidad aumenta según los días de inactividad:
  -- - 7-9 días: medium
  -- - 10-13 días: high
  -- - 14+ días: critical

  -- FIX-2026-01-19: Corregido p.user_id -> p.id
  -- student_id es FK a profiles(id), no a profiles(user_id)
  INSERT INTO progress_tracking.student_intervention_alerts
    (student_id, classroom_id, alert_type, severity, title, description, metrics, tenant_id)
  SELECT DISTINCT
    p.id,  -- FIX: Usar profiles.id (no user_id) ya que student_id FK apunta a profiles(id)
    mp.classroom_id,
    'no_activity'::TEXT,
    CASE
      WHEN EXTRACT(DAY FROM gamilit.now_mexico() - mp.last_accessed_at) >= 14 THEN 'critical'::TEXT
      WHEN EXTRACT(DAY FROM gamilit.now_mexico() - mp.last_accessed_at) >= 10 THEN 'high'::TEXT
      ELSE 'medium'::TEXT
    END,
    'Estudiante sin actividad reciente',
    format('El estudiante no ha tenido actividad en %s días',
      EXTRACT(DAY FROM gamilit.now_mexico() - mp.last_accessed_at)::INTEGER),
    jsonb_build_object(
      'days_inactive', EXTRACT(DAY FROM gamilit.now_mexico() - mp.last_accessed_at)::INTEGER,
      'last_activity', mp.last_accessed_at
    ),
    p.tenant_id
  FROM progress_tracking.module_progress mp
  JOIN auth_management.profiles p ON mp.user_id = p.id
  WHERE mp.last_accessed_at < gamilit.now_mexico() - INTERVAL '7 days'
    AND mp.status != 'completed'::progress_tracking.progress_status
    AND mp.classroom_id IS NOT NULL
    -- Prevenir alertas duplicadas (no generar si ya existe alerta activa reciente)
    AND NOT EXISTS (
      SELECT 1 FROM progress_tracking.student_intervention_alerts sia
      WHERE sia.student_id = mp.user_id
        AND sia.classroom_id = mp.classroom_id
        AND sia.alert_type = 'no_activity'
        AND sia.status = 'active'
        AND sia.generated_at > gamilit.now_mexico() - INTERVAL '5 days'
    );

  GET DIAGNOSTICS v_no_activity_count = ROW_COUNT;

  -- ============================================================================
  -- 2. DETECTAR BAJO RENDIMIENTO (score < 60%)
  -- ============================================================================
  -- Genera alertas para estudiantes con promedio de calificación bajo
  -- La severidad varía según el nivel de bajo rendimiento:
  -- - 50-59%: medium
  -- - 40-49%: high
  -- - <40%: critical
  -- Requiere mínimo 3 ejercicios intentados para evitar falsos positivos

  -- FIX-2026-01-19: Corregido p.user_id -> p.id
  INSERT INTO progress_tracking.student_intervention_alerts
    (student_id, classroom_id, alert_type, severity, title, description, metrics, tenant_id)
  SELECT
    p.id,  -- FIX: Usar profiles.id (no user_id) ya que student_id FK apunta a profiles(id)
    mp.classroom_id,
    'low_score'::TEXT,
    CASE
      WHEN mp.average_score < 40 THEN 'critical'::TEXT
      WHEN mp.average_score < 50 THEN 'high'::TEXT
      WHEN mp.average_score < 60 THEN 'medium'::TEXT
      ELSE 'low'::TEXT
    END,
    'Bajo rendimiento académico',
    format('Promedio de calificación: %s%% (Umbral recomendado: 60%%)', ROUND(mp.average_score, 1)),
    jsonb_build_object(
      'score', mp.average_score,
      'threshold', 60,
      'exercises_attempted', mp.total_exercises
    ),
    p.tenant_id
  FROM progress_tracking.module_progress mp
  JOIN auth_management.profiles p ON mp.user_id = p.id
  WHERE mp.average_score < 60
    AND mp.total_exercises >= 3
    AND mp.classroom_id IS NOT NULL
    -- Prevenir alertas duplicadas (no generar si ya existe alerta activa reciente)
    AND NOT EXISTS (
      SELECT 1 FROM progress_tracking.student_intervention_alerts sia
      WHERE sia.student_id = mp.user_id
        AND sia.classroom_id = mp.classroom_id
        AND sia.alert_type = 'low_score'
        AND sia.status = 'active'
        AND sia.generated_at > gamilit.now_mexico() - INTERVAL '3 days'
    );

  GET DIAGNOSTICS v_low_score_count = ROW_COUNT;

  -- ============================================================================
  -- 3. DETECTAR INTENTOS REPETIDOS FALLIDOS (>5 attempts en mismo ejercicio)
  -- ============================================================================
  -- Genera alertas cuando un estudiante tiene dificultad persistente con un ejercicio
  -- La severidad aumenta con el número de intentos:
  -- - 6-7 intentos: low
  -- - 8-10 intentos: medium
  -- - 11+ intentos: high

  -- FIX-DB-006-2026-01-18: Corregido attempts -> attempt_number, agregado JOIN a exercises
  -- FIX-2026-01-19: Corregido p.user_id -> p.id
  INSERT INTO progress_tracking.student_intervention_alerts
    (student_id, classroom_id, alert_type, severity, title, description, metrics, tenant_id)
  SELECT
    p.id,  -- FIX: Usar profiles.id (no user_id) ya que student_id FK apunta a profiles(id)
    mp.classroom_id,
    'repeated_failures'::TEXT,
    CASE
      WHEN es.attempt_number > 10 THEN 'high'::TEXT
      WHEN es.attempt_number > 7 THEN 'medium'::TEXT
      ELSE 'low'::TEXT
    END,
    'Dificultad persistente en ejercicio',
    format('El estudiante ha intentado %s veces el mismo ejercicio sin éxito', es.attempt_number),
    jsonb_build_object(
      'exercise_id', es.exercise_id,
      'attempts', es.attempt_number,
      'module_id', e.module_id
    ),
    p.tenant_id
  FROM progress_tracking.exercise_submissions es
  JOIN educational_content.exercises e ON es.exercise_id = e.id
  JOIN progress_tracking.module_progress mp ON es.user_id = mp.user_id
    AND e.module_id = mp.module_id
  JOIN auth_management.profiles p ON es.user_id = p.id
  WHERE es.attempt_number > 5
    AND es.status != 'correct'
    AND mp.classroom_id IS NOT NULL
    -- Prevenir alertas duplicadas (no generar si ya existe alerta activa reciente para mismo ejercicio)
    AND NOT EXISTS (
      SELECT 1 FROM progress_tracking.student_intervention_alerts sia
      WHERE sia.student_id = es.user_id
        AND sia.alert_type = 'repeated_failures'
        AND sia.metrics->>'exercise_id' = es.exercise_id::TEXT
        AND sia.status = 'active'
        AND sia.generated_at > gamilit.now_mexico() - INTERVAL '2 days'
    );

  GET DIAGNOSTICS v_repeated_failures_count = ROW_COUNT;

  -- ============================================================================
  -- 4. DETECTAR TENDENCIA DECRECIENTE (declining_trend)
  -- ============================================================================
  -- Genera alertas cuando el promedio de la última semana es significativamente
  -- menor que el de la semana anterior (>20% de caída)
  --
  -- TODO: Implementación completa requiere datos históricos de scores semanales.
  -- Esta versión básica compara submissions recientes vs anteriores.

  INSERT INTO progress_tracking.student_intervention_alerts
    (student_id, classroom_id, alert_type, severity, title, description, metrics, tenant_id)
  SELECT
    recent.user_id,
    mp.classroom_id,
    'declining_trend'::TEXT,
    CASE
      WHEN recent.avg_score < prev.avg_score * 0.6 THEN 'critical'::TEXT
      WHEN recent.avg_score < prev.avg_score * 0.7 THEN 'high'::TEXT
      ELSE 'medium'::TEXT
    END,
    'Tendencia decreciente en rendimiento',
    format('El rendimiento ha bajado de %s%% a %s%% en las últimas 2 semanas',
      ROUND(prev.avg_score, 1), ROUND(recent.avg_score, 1)),
    jsonb_build_object(
      'previous_week_avg', prev.avg_score,
      'recent_week_avg', recent.avg_score,
      'decline_percentage', ROUND(((prev.avg_score - recent.avg_score) / NULLIF(prev.avg_score, 0)) * 100, 1)
    ),
    p.tenant_id
  FROM (
    -- Promedio última semana
    -- FIX-DB-002-2026-01-18: Cambiado final_score -> score (columna correcta)
    SELECT user_id, AVG(score) as avg_score, COUNT(*) as count
    FROM progress_tracking.exercise_submissions
    WHERE submitted_at > gamilit.now_mexico() - INTERVAL '7 days'
      AND score IS NOT NULL
    GROUP BY user_id
    HAVING COUNT(*) >= 2
  ) recent
  JOIN (
    -- Promedio semana anterior
    -- FIX-DB-002-2026-01-18: Cambiado final_score -> score (columna correcta)
    SELECT user_id, AVG(score) as avg_score
    FROM progress_tracking.exercise_submissions
    WHERE submitted_at BETWEEN gamilit.now_mexico() - INTERVAL '14 days'
                           AND gamilit.now_mexico() - INTERVAL '7 days'
      AND score IS NOT NULL
    GROUP BY user_id
    HAVING COUNT(*) >= 2
  ) prev ON recent.user_id = prev.user_id
  JOIN progress_tracking.module_progress mp ON recent.user_id = mp.user_id
  JOIN auth_management.profiles p ON recent.user_id = p.id
  WHERE recent.avg_score < prev.avg_score * 0.8  -- 20% decline threshold
    AND mp.classroom_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM progress_tracking.student_intervention_alerts sia
      WHERE sia.student_id = recent.user_id
        AND sia.alert_type = 'declining_trend'
        AND sia.status = 'active'
        AND sia.generated_at > gamilit.now_mexico() - INTERVAL '7 days'
    );

  -- ============================================================================
  -- 5. DETECTAR TIEMPO EXCESIVO (excessive_time)
  -- ============================================================================
  -- Genera alertas cuando un estudiante gasta significativamente más tiempo
  -- del esperado en ejercicios (>2x del promedio general)

  INSERT INTO progress_tracking.student_intervention_alerts
    (student_id, classroom_id, alert_type, severity, title, description, metrics, tenant_id)
  SELECT
    es.user_id,
    mp.classroom_id,
    'excessive_time'::TEXT,
    CASE
      WHEN es.avg_time > avg_all.overall_avg * 3 THEN 'high'::TEXT
      WHEN es.avg_time > avg_all.overall_avg * 2 THEN 'medium'::TEXT
      ELSE 'low'::TEXT
    END,
    'Tiempo excesivo en ejercicios',
    format('Tiempo promedio: %s min (General: %s min)',
      ROUND(es.avg_time / 60, 1), ROUND(avg_all.overall_avg / 60, 1)),
    jsonb_build_object(
      'student_avg_seconds', es.avg_time,
      'overall_avg_seconds', avg_all.overall_avg,
      'ratio', ROUND(es.avg_time / NULLIF(avg_all.overall_avg, 1), 2)
    ),
    p.tenant_id
  FROM (
    -- Promedio de tiempo por estudiante (últimos 7 días)
    SELECT user_id, AVG(time_spent_seconds) as avg_time
    FROM progress_tracking.exercise_submissions
    WHERE submitted_at > gamilit.now_mexico() - INTERVAL '7 days'
      AND time_spent_seconds IS NOT NULL
      AND time_spent_seconds > 0
    GROUP BY user_id
    HAVING COUNT(*) >= 3
  ) es
  CROSS JOIN (
    -- Promedio general de todos los estudiantes
    SELECT AVG(time_spent_seconds) as overall_avg
    FROM progress_tracking.exercise_submissions
    WHERE submitted_at > gamilit.now_mexico() - INTERVAL '30 days'
      AND time_spent_seconds IS NOT NULL
      AND time_spent_seconds > 0
  ) avg_all
  JOIN progress_tracking.module_progress mp ON es.user_id = mp.user_id
  JOIN auth_management.profiles p ON es.user_id = p.id
  WHERE es.avg_time > avg_all.overall_avg * 2  -- 2x threshold
    AND mp.classroom_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM progress_tracking.student_intervention_alerts sia
      WHERE sia.student_id = es.user_id
        AND sia.alert_type = 'excessive_time'
        AND sia.status = 'active'
        AND sia.generated_at > gamilit.now_mexico() - INTERVAL '5 days'
    );

  -- ============================================================================
  -- 6. DETECTAR BAJO ENGAGEMENT (low_engagement)
  -- ============================================================================
  -- Genera alertas cuando un estudiante tiene muy poca actividad semanal
  -- (menos de 2 ejercicios por semana o menos de 30 minutos totales)

  INSERT INTO progress_tracking.student_intervention_alerts
    (student_id, classroom_id, alert_type, severity, title, description, metrics, tenant_id)
  SELECT
    activity.user_id,
    mp.classroom_id,
    'low_engagement'::TEXT,
    CASE
      WHEN activity.exercise_count = 0 THEN 'high'::TEXT
      WHEN activity.exercise_count = 1 THEN 'medium'::TEXT
      ELSE 'low'::TEXT
    END,
    'Bajo nivel de engagement',
    format('Solo %s ejercicios completados esta semana (mínimo recomendado: 3)',
      activity.exercise_count),
    jsonb_build_object(
      'weekly_exercises', activity.exercise_count,
      'weekly_time_minutes', ROUND(activity.total_time / 60, 1),
      'minimum_recommended', 3
    ),
    p.tenant_id
  FROM (
    -- Actividad de la última semana por estudiante
    SELECT
      user_id,
      COUNT(*) as exercise_count,
      COALESCE(SUM(time_spent_seconds), 0) as total_time
    FROM progress_tracking.exercise_submissions
    WHERE submitted_at > gamilit.now_mexico() - INTERVAL '7 days'
    GROUP BY user_id
    HAVING COUNT(*) < 3 OR COALESCE(SUM(time_spent_seconds), 0) < 1800  -- menos de 3 ejercicios o 30 min
  ) activity
  JOIN progress_tracking.module_progress mp ON activity.user_id = mp.user_id
  JOIN auth_management.profiles p ON activity.user_id = p.id
  WHERE mp.classroom_id IS NOT NULL
    AND mp.status NOT IN ('completed'::progress_tracking.progress_status, 'not_started'::progress_tracking.progress_status)
    AND NOT EXISTS (
      SELECT 1 FROM progress_tracking.student_intervention_alerts sia
      WHERE sia.student_id = activity.user_id
        AND sia.alert_type = 'low_engagement'
        AND sia.status = 'active'
        AND sia.generated_at > gamilit.now_mexico() - INTERVAL '5 days'
    );

  -- ============================================================================
  -- LOGGING Y RESUMEN
  -- ============================================================================

  v_alerts_count := v_no_activity_count + v_low_score_count + v_repeated_failures_count;

  RAISE NOTICE 'Alertas generadas exitosamente en %', gamilit.now_mexico();
  RAISE NOTICE '  - Sin actividad: %', v_no_activity_count;
  RAISE NOTICE '  - Bajo rendimiento: %', v_low_score_count;
  RAISE NOTICE '  - Fallos repetidos: %', v_repeated_failures_count;
  RAISE NOTICE '  - Total: %', v_alerts_count;

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Error al generar alertas: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    -- No re-lanzar el error para permitir que el job continue
END;
$$;


ALTER FUNCTION progress_tracking.generate_student_alerts() OWNER TO postgres;

--
-- Name: FUNCTION generate_student_alerts(); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.generate_student_alerts() IS 'Genera alertas automáticas de intervención basadas en métricas de estudiantes. Debe ejecutarse diariamente vía CRON o scheduler. Detecta: inactividad (7+ días), bajo rendimiento (<60%), fallos repetidos (>5 intentos), tendencia decreciente (>20% baja), tiempo excesivo (>2x promedio), bajo engagement (<3 ejercicios/semana).';


--
-- Name: get_classroom_analytics(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.get_classroom_analytics(p_classroom_id uuid, p_date_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_date_to timestamp with time zone DEFAULT now()) RETURNS TABLE(total_students integer, active_students integer, avg_completion_rate numeric, total_missions_completed integer, total_xp_earned bigint, avg_current_streak numeric, top_performer_id uuid, top_performer_name character varying, top_performer_xp bigint)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    WITH classroom_students AS (
        SELECT user_id
        FROM social_features.classroom_members
        WHERE classroom_id = p_classroom_id
          AND joined_at BETWEEN p_date_from AND p_date_to
    ),
    student_stats AS (
        SELECT
            cs.user_id,
            us.total_xp,
            us.modules_completed,
            us.current_streak,
            us.last_activity_at
        FROM classroom_students cs
        JOIN gamification_system.user_stats us ON us.user_id = cs.user_id
    )
    SELECT
        COUNT(*)::INTEGER as total_students,
        COUNT(*) FILTER (WHERE last_activity_at >= CURRENT_DATE - 7)::INTEGER as active_students,
        AVG(
            (SELECT completion_percentage
             FROM progress_tracking.module_progress mp
             WHERE mp.user_id = ss.user_id
             LIMIT 1)
        )::NUMERIC(5,2) as avg_completion_rate,
        SUM(modules_completed)::INTEGER as total_missions_completed,
        SUM(total_xp)::BIGINT as total_xp_earned,
        AVG(current_streak)::NUMERIC(5,2) as avg_current_streak,
        (SELECT user_id FROM student_stats ORDER BY total_xp DESC LIMIT 1) as top_performer_id,
        (SELECT full_name FROM auth_management.profiles WHERE id = (SELECT user_id FROM student_stats ORDER BY total_xp DESC LIMIT 1)) as top_performer_name,
        (SELECT total_xp FROM student_stats ORDER BY total_xp DESC LIMIT 1) as top_performer_xp
    FROM student_stats ss;
END;
$$;


ALTER FUNCTION progress_tracking.get_classroom_analytics(p_classroom_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone) OWNER TO postgres;

--
