COMMENT ON FUNCTION progress_tracking.promote_user_difficulty_level(p_user_id uuid, p_from_level educational_content.difficulty_level, p_to_level educational_content.difficulty_level) IS 'Promociona al usuario al siguiente nivel de dificultad CEFR y actualiza zona de desarrollo próximo (ZDP).
SECURITY DEFINER permite actualizar tablas sin permisos directos.';


--
-- Name: sync_all_module_progress_scores(); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.sync_all_module_progress_scores() RETURNS TABLE(user_id uuid, module_id uuid, old_score numeric, new_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Retornar cambios realizados
  RETURN QUERY
  WITH submissions_stats AS (
    SELECT
      es.user_id,
      e.module_id,
      ROUND(AVG(
        CASE
          WHEN es.max_score > 0 THEN (es.score::NUMERIC / es.max_score * 100)
          ELSE 0
        END
      ), 2) as calc_avg_score,
      COUNT(DISTINCT CASE WHEN es.is_correct = true THEN es.exercise_id END) as calc_completed,
      COUNT(DISTINCT es.exercise_id) as calc_total
    FROM progress_tracking.exercise_submissions es
    JOIN educational_content.exercises e ON es.exercise_id = e.id
    GROUP BY es.user_id, e.module_id
  ),
  updates AS (
    UPDATE progress_tracking.module_progress mp
    SET
      average_score = ss.calc_avg_score,
      completed_exercises = ss.calc_completed,
      total_exercises = GREATEST(mp.total_exercises, ss.calc_total),
      updated_at = NOW()
    FROM submissions_stats ss
    WHERE mp.user_id = ss.user_id
      AND mp.module_id = ss.module_id
    RETURNING mp.user_id, mp.module_id, mp.average_score as new_avg
  )
  SELECT
    u.user_id,
    u.module_id,
    NULL::NUMERIC as old_score,
    u.new_avg as new_score
  FROM updates u;
END;
$$;


ALTER FUNCTION progress_tracking.sync_all_module_progress_scores() OWNER TO postgres;

--
-- Name: FUNCTION sync_all_module_progress_scores(); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.sync_all_module_progress_scores() IS 'Sincroniza todos los module_progress que tienen exercise_submissions. Retorna los cambios realizados.';


--
-- Name: sync_module_progress_scores(uuid, uuid); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.sync_module_progress_scores(p_user_id uuid, p_module_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_avg_score NUMERIC(5,2);
  v_completed_count INTEGER;
  v_total_count INTEGER;
  v_updated INTEGER;
BEGIN
  -- Calcular estadisticas desde exercise_submissions
  -- Solo considera ejercicios del modulo especificado
  SELECT
    ROUND(AVG(
      CASE
        WHEN es.max_score > 0 THEN (es.score::NUMERIC / es.max_score * 100)
        ELSE 0
      END
    ), 2),
    COUNT(DISTINCT CASE WHEN es.is_correct = true THEN es.exercise_id END),
    COUNT(DISTINCT es.exercise_id)
  INTO v_avg_score, v_completed_count, v_total_count
  FROM progress_tracking.exercise_submissions es
  JOIN educational_content.exercises e ON es.exercise_id = e.id
  WHERE es.user_id = p_user_id
    AND e.module_id = p_module_id;

  -- Si no hay submissions, no hacer nada
  IF v_total_count = 0 THEN
    RETURN;
  END IF;

  -- Actualizar module_progress
  UPDATE progress_tracking.module_progress
  SET
    average_score = COALESCE(v_avg_score, 0),
    completed_exercises = COALESCE(v_completed_count, 0),
    total_exercises = GREATEST(total_exercises, COALESCE(v_total_count, 0)),
    updated_at = NOW()
  WHERE user_id = p_user_id
    AND module_id = p_module_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Si no existe module_progress, crear uno
  IF v_updated = 0 THEN
    INSERT INTO progress_tracking.module_progress (
      user_id,
      module_id,
      average_score,
      completed_exercises,
      total_exercises,
      status,
      progress_percentage
    ) VALUES (
      p_user_id,
      p_module_id,
      COALESCE(v_avg_score, 0),
      COALESCE(v_completed_count, 0),
      COALESCE(v_total_count, 0),
      'in_progress',
      0
    )
    ON CONFLICT (user_id, module_id) DO UPDATE SET
      average_score = EXCLUDED.average_score,
      completed_exercises = EXCLUDED.completed_exercises,
      total_exercises = GREATEST(progress_tracking.module_progress.total_exercises, EXCLUDED.total_exercises),
      updated_at = NOW();
  END IF;

END;
$$;


ALTER FUNCTION progress_tracking.sync_module_progress_scores(p_user_id uuid, p_module_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION sync_module_progress_scores(p_user_id uuid, p_module_id uuid); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.sync_module_progress_scores(p_user_id uuid, p_module_id uuid) IS 'Sincroniza average_score, completed_exercises y total_exercises en module_progress basandose en exercise_submissions. Llamada automaticamente por trigger o manualmente.';


--
-- Name: update_difficulty_progress(uuid, educational_content.difficulty_level, boolean, boolean, integer); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.update_difficulty_progress(p_user_id uuid, p_difficulty_level educational_content.difficulty_level, p_is_completed boolean, p_is_correct_first_attempt boolean, p_time_spent_seconds integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_is_eligible BOOLEAN;
BEGIN
    -- Upsert del progreso
    INSERT INTO progress_tracking.user_difficulty_progress (
        user_id,
        difficulty_level,
        exercises_attempted,
        exercises_completed,
        exercises_correct_first_attempt,
        total_time_spent_seconds,
        first_attempt_at,
        last_attempt_at
    )
    VALUES (
        p_user_id,
        p_difficulty_level,
        1,
        CASE WHEN p_is_completed THEN 1 ELSE 0 END,
        CASE WHEN p_is_correct_first_attempt THEN 1 ELSE 0 END,
        p_time_spent_seconds,
        gamilit.now_mexico(),
        gamilit.now_mexico()
    )
    ON CONFLICT (user_id, difficulty_level)
    DO UPDATE SET
        exercises_attempted = progress_tracking.user_difficulty_progress.exercises_attempted + 1,
        exercises_completed = progress_tracking.user_difficulty_progress.exercises_completed +
            CASE WHEN p_is_completed THEN 1 ELSE 0 END,
        exercises_correct_first_attempt = progress_tracking.user_difficulty_progress.exercises_correct_first_attempt +
            CASE WHEN p_is_correct_first_attempt THEN 1 ELSE 0 END,
        total_time_spent_seconds = progress_tracking.user_difficulty_progress.total_time_spent_seconds + p_time_spent_seconds,
        last_attempt_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico();

    -- Verificar si ahora es elegible para promoción
    v_is_eligible := progress_tracking.check_difficulty_promotion_eligibility(p_user_id, p_difficulty_level);

    -- Actualizar flag de elegibilidad
    UPDATE progress_tracking.user_difficulty_progress
    SET is_ready_for_promotion = v_is_eligible
    WHERE user_id = p_user_id
      AND difficulty_level = p_difficulty_level;

    -- TODO: Si es elegible, crear notificación (requiere tabla notifications)

    -- Log
    IF v_is_eligible THEN
        RAISE NOTICE 'Usuario % ahora es elegible para promoción desde %',
            p_user_id, p_difficulty_level;
    END IF;
END;
$$;


ALTER FUNCTION progress_tracking.update_difficulty_progress(p_user_id uuid, p_difficulty_level educational_content.difficulty_level, p_is_completed boolean, p_is_correct_first_attempt boolean, p_time_spent_seconds integer) OWNER TO postgres;

--
