--
-- Name: update_module_progress_complete(); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.update_module_progress_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_module_id UUID;
    v_total_exercises INTEGER;
    v_completed_exercises INTEGER;
    v_graded_exercises INTEGER;
    v_avg_score NUMERIC(5,2);
    v_progress_percentage NUMERIC;
    v_graded_percentage NUMERIC;
    v_new_status progress_tracking.progress_status;
    v_current_status progress_tracking.progress_status;
    v_is_first_approved_for_exercise BOOLEAN;
    v_total_xp INTEGER;
    v_total_coins INTEGER;
BEGIN
    -- =======================================================================
    -- FILTRO RAPIDO: Solo procesar submissions con score >= 60
    -- =======================================================================
    IF NEW.score < 60 OR NEW.status NOT IN ('graded', 'reviewed') THEN
        RETURN NEW;
    END IF;

    -- =======================================================================
    -- PASO 1: Obtener module_id del ejercicio
    -- =======================================================================
    SELECT module_id INTO v_module_id
    FROM educational_content.exercises
    WHERE id = NEW.exercise_id;

    IF v_module_id IS NULL THEN
        RAISE WARNING 'Ejercicio % no tiene module_id asociado', NEW.exercise_id;
        RETURN NEW;
    END IF;

    -- =======================================================================
    -- PASO 2: Verificar si es el primer submission aprobado para este ejercicio
    -- =======================================================================
    SELECT NOT EXISTS (
        SELECT 1 FROM progress_tracking.exercise_submissions
        WHERE user_id = NEW.user_id
          AND exercise_id = NEW.exercise_id
          AND score >= 60
          AND status IN ('graded', 'reviewed')
          AND id != NEW.id
    ) INTO v_is_first_approved_for_exercise;

    -- Si no es el primer aprobado, solo actualizar timestamps y average_score
    IF NOT v_is_first_approved_for_exercise THEN
        -- Aun asi necesitamos recalcular average_score (un nuevo submission puede cambiar el promedio)
        SELECT
            ROUND(AVG(
                CASE
                    WHEN es.max_score > 0 THEN (es.score::NUMERIC / es.max_score * 100)
                    ELSE es.score
                END
            ), 2)
        INTO v_avg_score
        FROM progress_tracking.exercise_submissions es
        JOIN educational_content.exercises e ON es.exercise_id = e.id
        WHERE es.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND es.status IN ('graded', 'reviewed');

        UPDATE progress_tracking.module_progress
        SET
            average_score = COALESCE(v_avg_score, average_score),
            last_accessed_at = gamilit.now_mexico(),
            updated_at = gamilit.now_mexico()
        WHERE user_id = NEW.user_id AND module_id = v_module_id;

        RETURN NEW;
    END IF;

    -- =======================================================================
    -- PASO 3: Calcular TODAS las metricas en una sola operacion
    -- =======================================================================

    -- 3.1 Total de ejercicios activos en el modulo
    SELECT COUNT(*)
    INTO v_total_exercises
    FROM educational_content.exercises
    WHERE module_id = v_module_id AND is_active = true;

    -- 3.2 Ejercicios completados (UNION attempts + submissions) + average_score
    --     Consolidamos el query de sync_module_progress_scores aqui
    WITH completed_exercises AS (
        -- Ejercicios auto-calificados correctos (attempts)
        SELECT ea.exercise_id
        FROM progress_tracking.exercise_attempts ea
        JOIN educational_content.exercises e ON e.id = ea.exercise_id
        WHERE ea.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND ea.is_correct = true

        UNION

        -- Ejercicios con revision manual aprobados (submissions)
        SELECT es.exercise_id
        FROM progress_tracking.exercise_submissions es
        JOIN educational_content.exercises e ON e.id = es.exercise_id
        WHERE es.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND es.score >= 60
          AND es.status IN ('graded', 'reviewed')
    ),
    graded_exercises AS (
        SELECT DISTINCT es.exercise_id
        FROM progress_tracking.exercise_submissions es
        JOIN educational_content.exercises e ON e.id = es.exercise_id
        WHERE es.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND es.status IN ('graded', 'reviewed')
    ),
    score_stats AS (
        SELECT
            ROUND(AVG(
                CASE
                    WHEN es.max_score > 0 THEN (es.score::NUMERIC / es.max_score * 100)
                    ELSE es.score
                END
            ), 2) as avg_score,
            COALESCE(SUM(es.xp_earned), 0) as total_xp,
            COALESCE(SUM(es.ml_coins_earned), 0) as total_coins
        FROM progress_tracking.exercise_submissions es
        JOIN educational_content.exercises e ON e.id = es.exercise_id
        WHERE es.user_id = NEW.user_id
          AND e.module_id = v_module_id
          AND es.status IN ('graded', 'reviewed')
    )
    SELECT
        (SELECT COUNT(*) FROM completed_exercises),
        (SELECT COUNT(*) FROM graded_exercises),
        ss.avg_score,
        ss.total_xp,
        ss.total_coins
    INTO v_completed_exercises, v_graded_exercises, v_avg_score, v_total_xp, v_total_coins
    FROM score_stats ss;

    -- =======================================================================
    -- PASO 4: Calcular porcentajes de progreso
    -- =======================================================================
    IF v_total_exercises > 0 THEN
        v_progress_percentage := ROUND((v_completed_exercises::NUMERIC / v_total_exercises::NUMERIC) * 100, 2);
        v_graded_percentage := ROUND((v_graded_exercises::NUMERIC / v_total_exercises::NUMERIC) * 100, 2);
    ELSE
        v_progress_percentage := 0;
        v_graded_percentage := 0;
    END IF;

    -- =======================================================================
    -- PASO 5: Determinar nuevo status
    -- =======================================================================
    IF v_progress_percentage >= 100 THEN
        v_new_status := 'completed';
    ELSIF v_progress_percentage > 0 THEN
        v_new_status := 'in_progress';
    ELSE
        v_new_status := 'not_started';
    END IF;

    -- Obtener status actual
    SELECT status INTO v_current_status
    FROM progress_tracking.module_progress
    WHERE user_id = NEW.user_id AND module_id = v_module_id;

    -- =======================================================================
    -- PASO 6: UPSERT module_progress (una sola operacion)
    -- =======================================================================
    INSERT INTO progress_tracking.module_progress (
        user_id,
        module_id,
        status,
        progress_percentage,
        completed_exercises,
        total_exercises,
        graded_exercises,
        graded_progress_percentage,
        average_score,
        total_xp_earned,
        total_ml_coins_earned,
        started_at,
        last_accessed_at,
        completed_at,
        updated_at
    ) VALUES (
        NEW.user_id,
        v_module_id,
        v_new_status,
        v_progress_percentage,
        v_completed_exercises,
        v_total_exercises,
        v_graded_exercises,
        v_graded_percentage,
        COALESCE(v_avg_score, 0),
        COALESCE(v_total_xp, 0),
        COALESCE(v_total_coins, 0),
        gamilit.now_mexico(),
        gamilit.now_mexico(),
        CASE WHEN v_new_status = 'completed' THEN gamilit.now_mexico() ELSE NULL END,
        gamilit.now_mexico()
    )
    ON CONFLICT (user_id, module_id) DO UPDATE SET
        completed_exercises = EXCLUDED.completed_exercises,
        total_exercises = EXCLUDED.total_exercises,
        progress_percentage = EXCLUDED.progress_percentage,
        graded_exercises = EXCLUDED.graded_exercises,
        graded_progress_percentage = EXCLUDED.graded_progress_percentage,
        average_score = EXCLUDED.average_score,
        total_xp_earned = EXCLUDED.total_xp_earned,
        total_ml_coins_earned = EXCLUDED.total_ml_coins_earned,
        status = EXCLUDED.status,
        -- Solo actualizar completed_at si cambia a completed
        completed_at = CASE
            WHEN EXCLUDED.status = 'completed' AND progress_tracking.module_progress.completed_at IS NULL
            THEN gamilit.now_mexico()
            ELSE progress_tracking.module_progress.completed_at
        END,
        -- Solo actualizar started_at si es NULL
        started_at = COALESCE(progress_tracking.module_progress.started_at, gamilit.now_mexico()),
        last_accessed_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico();

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no bloquear el update del submission
        RAISE WARNING 'Error al actualizar progreso de modulo para usuario % en submission %: %',
            NEW.user_id, NEW.id, SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION progress_tracking.update_module_progress_complete() OWNER TO postgres;

--
-- Name: FUNCTION update_module_progress_complete(); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.update_module_progress_complete() IS 'Trigger function CONSOLIDADA que combina trg_update_module_progress y trg_sync_average_score. Actualiza progress_percentage, completed_exercises, graded_exercises, y average_score en UNA sola operacion. Reduce latencia de 60-105ms a 50-80ms (-20-25%) por submission calificada. Creada: TASK-2026-02-02-IMPLEMENTAR-OPTIMIZACION-TRIGGERS';


--
-- Name: update_submitted_progress_on_submission(); Type: FUNCTION; Schema: progress_tracking; Owner: postgres
--

CREATE FUNCTION progress_tracking.update_submitted_progress_on_submission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_module_id UUID;
  v_classroom_id UUID;
  v_total_exercises INT;
  v_submitted_count INT;
  v_submitted_percentage NUMERIC(5,2);
BEGIN
  -- Obtener module_id del ejercicio
  SELECT e.module_id INTO v_module_id
  FROM educational_content.exercises e
  WHERE e.id = NEW.exercise_id;

  IF v_module_id IS NULL THEN
    -- Ejercicio no encontrado o sin modulo, no hacer nada
    RETURN NEW;
  END IF;

  -- Obtener classroom_id del module_progress existente (si existe)
  SELECT mp.classroom_id INTO v_classroom_id
  FROM progress_tracking.module_progress mp
  WHERE mp.user_id = NEW.user_id AND mp.module_id = v_module_id
  LIMIT 1;

  -- Contar ejercicios totales activos del modulo
  SELECT COUNT(*) INTO v_total_exercises
  FROM educational_content.exercises e
  WHERE e.module_id = v_module_id AND e.is_active = true;

  IF v_total_exercises = 0 THEN
    -- Modulo sin ejercicios, no hacer nada
    RETURN NEW;
  END IF;

  -- Contar submissions unicos del usuario en este modulo
  -- (cualquier status excepto 'draft')
  SELECT COUNT(DISTINCT es.exercise_id) INTO v_submitted_count
  FROM progress_tracking.exercise_submissions es
  JOIN educational_content.exercises e ON es.exercise_id = e.id
  WHERE es.user_id = NEW.user_id
    AND e.module_id = v_module_id
    AND es.status IN ('submitted', 'pending_review', 'graded', 'reviewed');

  -- Calcular porcentaje
  v_submitted_percentage := ROUND((v_submitted_count::NUMERIC / v_total_exercises) * 100, 2);

  -- Actualizar module_progress (INSERT si no existe)
  INSERT INTO progress_tracking.module_progress (
    user_id,
    module_id,
    classroom_id,
    submitted_exercises,
    submitted_progress_percentage,
    status,
    updated_at
  )
  VALUES (
    NEW.user_id,
    v_module_id,
    v_classroom_id,
    v_submitted_count,
    v_submitted_percentage,
    CASE
      WHEN v_submitted_count > 0 THEN 'in_progress'::progress_tracking.progress_status
      ELSE 'not_started'::progress_tracking.progress_status
    END,
    NOW()
  )
  ON CONFLICT (user_id, module_id)
  DO UPDATE SET
    submitted_exercises = v_submitted_count,
    submitted_progress_percentage = v_submitted_percentage,
    status = CASE
      WHEN progress_tracking.module_progress.status = 'completed' THEN 'completed'::progress_tracking.progress_status
      WHEN v_submitted_count > 0 THEN 'in_progress'::progress_tracking.progress_status
      ELSE progress_tracking.module_progress.status
    END,
    updated_at = NOW();

  RETURN NEW;
END;
$$;


ALTER FUNCTION progress_tracking.update_submitted_progress_on_submission() OWNER TO postgres;

--
-- Name: FUNCTION update_submitted_progress_on_submission(); Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON FUNCTION progress_tracking.update_submitted_progress_on_submission() IS 'FIX-DB-003-2026-01-18: Actualiza submitted_exercises y submitted_progress_percentage en module_progress cuando se crea un nuevo submission. Soporta feature M3-M5 de tracking separado entre enviados vs calificados.';


--
-- Name: accept_friend_request(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.accept_friend_request(p_request_id uuid, p_recipient_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_requester_id UUID;
    v_recipient_id UUID;
BEGIN
    -- Verificar que la solicitud existe, está pendiente y el usuario es el destinatario
    SELECT requester_id, recipient_id
    INTO v_requester_id, v_recipient_id
    FROM social_features.friend_requests
    WHERE id = p_request_id
      AND recipient_id = p_recipient_id
      AND status = 'pending';

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    -- Actualizar solicitud a 'accepted'
    UPDATE social_features.friend_requests
    SET status = 'accepted',
        responded_at = gamilit.now_mexico()
    WHERE id = p_request_id;

    -- Crear amistad (bidireccional: insertar solo una vez)
    INSERT INTO social_features.friendships (user_id, friend_id)
    VALUES (v_requester_id, v_recipient_id)
    ON CONFLICT (user_id, friend_id) DO NOTHING;

    RETURN TRUE;
END;
$$;


ALTER FUNCTION social_features.accept_friend_request(p_request_id uuid, p_recipient_id uuid) OWNER TO postgres;

