--
-- Name: cancel_friend_request(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.cancel_friend_request(p_request_id uuid, p_requester_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Actualizar solicitud a 'cancelled' o eliminarla
    DELETE FROM social_features.friend_requests
    WHERE id = p_request_id
      AND requester_id = p_requester_id
      AND status = 'pending';

    RETURN FOUND;
END;
$$;


