--
-- Name: cleanup_old_notifications(integer); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.cleanup_old_notifications(p_days_to_keep integer DEFAULT 30) RETURNS TABLE(deleted_count integer, oldest_kept_date timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cutoff_date TIMESTAMPTZ;
    v_deleted INTEGER;
BEGIN
    v_cutoff_date := NOW() - (p_days_to_keep || ' days')::INTERVAL;

    DELETE FROM social_features.notifications
    WHERE created_at < v_cutoff_date
      AND is_read = true;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RETURN QUERY SELECT
        v_deleted,
        v_cutoff_date;
END;
$$;


ALTER FUNCTION social_features.cleanup_old_notifications(p_days_to_keep integer) OWNER TO postgres;

--
-- Name: FUNCTION cleanup_old_notifications(p_days_to_keep integer); Type: COMMENT; Schema: social_features; Owner: postgres
--

COMMENT ON FUNCTION social_features.cleanup_old_notifications(p_days_to_keep integer) IS 'Limpia notificaciones leídas más antiguas que el período especificado';


--
-- Name: count_blocked_users(uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.count_blocked_users(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    block_count INTEGER;
BEGIN
    SELECT COUNT(*)::INTEGER INTO block_count
    FROM social_features.user_blocks
    WHERE blocker_id = p_user_id;

    RETURN COALESCE(block_count, 0);
END;
$$;


