--
-- Name: get_user_friends(uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.get_user_friends(p_user_id uuid) RETURNS TABLE(friend_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        CASE
            WHEN f.user_id = p_user_id THEN f.friend_id
            ELSE f.user_id
        END AS friend_id,
        f.created_at
    FROM social_features.friendships f
    WHERE f.user_id = p_user_id OR f.friend_id = p_user_id
    ORDER BY f.created_at DESC;
END;
$$;


