--
-- Name: has_pending_friend_request(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.has_pending_friend_request(user1_id uuid, user2_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM social_features.friend_requests
        WHERE status = 'pending'
          AND (
              (requester_id = user1_id AND recipient_id = user2_id)
              OR (requester_id = user2_id AND recipient_id = user1_id)
          )
    );
END;
$$;


