-- Name: sync_teacher_classroom_on_insert(); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.sync_teacher_classroom_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Al crear un classroom, automaticamente crear registro en teacher_classrooms
    -- con el profesor principal como 'owner'
    INSERT INTO social_features.teacher_classrooms (
        teacher_id,
        classroom_id,
        tenant_id,
        role,
        assigned_at
    ) VALUES (
        NEW.teacher_id,
        NEW.id,
        NEW.tenant_id,
        'owner',
        NEW.created_at
    )
    ON CONFLICT (teacher_id, classroom_id) DO NOTHING;

    RETURN NEW;
END;
$$;


