--
-- Name: update_guild_member_count(); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.update_guild_member_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE social_features.guilds
        SET member_count = member_count + 1,
            last_activity_at = gamilit.now_mexico()
        WHERE id = NEW.guild_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE social_features.guilds
        SET member_count = GREATEST(member_count - 1, 0)
        WHERE id = OLD.guild_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


