--
-- Name: update_feature_flag(text, boolean, integer, text); Type: FUNCTION; Schema: system_configuration; Owner: postgres
--

CREATE FUNCTION system_configuration.update_feature_flag(p_feature_key text, p_enabled boolean, p_rollout_percentage integer DEFAULT 100, p_description text DEFAULT NULL::text) RETURNS TABLE(feature_id uuid, key text, enabled boolean, rollout_percentage integer, status_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'system_configuration', 'audit_logging'
    AS $$
DECLARE
    v_feature_id UUID;
    v_message TEXT;
BEGIN
    -- Validate rollout percentage
    IF p_rollout_percentage < 0 OR p_rollout_percentage > 100 THEN
        RAISE EXCEPTION 'Rollout percentage must be between 0 and 100';
    END IF;

    -- Try to update existing feature flag
    UPDATE system_configuration.feature_flags
    SET
        enabled = p_enabled,
        rollout_percentage = p_rollout_percentage,
        description = COALESCE(p_description, description),
        updated_at = NOW()
    WHERE key = p_feature_key
    RETURNING id INTO v_feature_id;

    -- If feature doesn't exist, create it
    IF v_feature_id IS NULL THEN
        INSERT INTO system_configuration.feature_flags (
            key,
            enabled,
            rollout_percentage,
            description,
            is_active,
            created_at
        ) VALUES (
            p_feature_key,
            p_enabled,
            p_rollout_percentage,
            p_description,
            TRUE,
            NOW()
        )
        RETURNING id INTO v_feature_id;

        v_message := FORMAT('Feature flag ''%s'' created successfully', p_feature_key);
    ELSE
        v_message := FORMAT('Feature flag ''%s'' updated successfully', p_feature_key);
    END IF;

    -- Log the feature flag update
    PERFORM audit_logging.log_system_event(
        'FEATURE_FLAG_UPDATED',
        'feature_management',
        jsonb_build_object(
            'feature_key', p_feature_key,
            'enabled', p_enabled,
            'rollout_percentage', p_rollout_percentage
        ),
        'INFO'
    );

    RETURN QUERY SELECT
        v_feature_id,
        p_feature_key,
        p_enabled,
        p_rollout_percentage,
        v_message;

EXCEPTION WHEN OTHERS THEN
    v_message := FORMAT('Error updating feature flag: %s', SQLERRM);
    RETURN QUERY SELECT
        NULL,
        p_feature_key,
        FALSE,
        0,
        v_message;
END;
$$;


ALTER FUNCTION system_configuration.update_feature_flag(p_feature_key text, p_enabled boolean, p_rollout_percentage integer, p_description text) OWNER TO postgres;

--
-- Name: FUNCTION update_feature_flag(p_feature_key text, p_enabled boolean, p_rollout_percentage integer, p_description text); Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON FUNCTION system_configuration.update_feature_flag(p_feature_key text, p_enabled boolean, p_rollout_percentage integer, p_description text) IS 'Updates feature flag status and manages rollout configurations for gradual feature deployment.
Parameters:
  - p_feature_key: Unique identifier for the feature flag
  - p_enabled: Whether the feature is enabled globally
  - p_rollout_percentage: Percentage of users who should see the feature (0-100, default: 100)
  - p_description: Optional description of the feature flag
Returns:
  - feature_id: UUID of the feature flag
  - key: Feature key
  - enabled: Current enabled status
  - rollout_percentage: Current rollout percentage
  - status_message: Operation result message
Example:
  SELECT update_feature_flag(
    ''dark_mode''::TEXT,
    TRUE,
    50,
    ''Gradual rollout of dark mode''::TEXT
  );';


--
-- Name: update_feature_flags_timestamp(); Type: FUNCTION; Schema: system_configuration; Owner: postgres
--

CREATE FUNCTION system_configuration.update_feature_flags_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();

    -- Track when flag was enabled/disabled
    IF NEW.is_enabled = TRUE AND OLD.is_enabled = FALSE THEN
        NEW.enabled_at = NOW();
    ELSIF NEW.is_enabled = FALSE AND OLD.is_enabled = TRUE THEN
        NEW.disabled_at = NOW();
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION system_configuration.update_feature_flags_timestamp() OWNER TO postgres;

--
-- Name: update_gamification_parameters_timestamp(); Type: FUNCTION; Schema: system_configuration; Owner: postgres
--

CREATE FUNCTION system_configuration.update_gamification_parameters_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    NEW.last_modified_at = NOW();
    NEW.usage_count = COALESCE(OLD.usage_count, 0) + 1;
    RETURN NEW;
END;
$$;


