--
-- Name: classroom_summary_mv; Type: MATERIALIZED VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE MATERIALIZED VIEW admin_dashboard.classroom_summary_mv AS
 SELECT id AS classroom_id,
    name AS classroom_name,
    description,
    grade_level,
    subject,
    code AS classroom_code,
    is_active,
    created_at,
    ( SELECT p.display_name
           FROM (auth_management.profiles p
             JOIN social_features.teacher_classrooms tc ON ((tc.teacher_id = p.id)))
          WHERE (tc.classroom_id = c.id)
         LIMIT 1) AS primary_teacher_name,
    ( SELECT count(*) AS count
           FROM social_features.classroom_members cm
          WHERE ((cm.classroom_id = c.id) AND (cm.is_active = true))) AS student_count,
    ( SELECT count(*) AS count
           FROM social_features.classroom_members cm
          WHERE ((cm.classroom_id = c.id) AND (cm.is_active = true) AND (cm.enrollment_date >= (CURRENT_DATE - '7 days'::interval)))) AS new_students_week,
    ( SELECT count(*) AS count
           FROM educational_content.classroom_modules clm
          WHERE ((clm.classroom_id = c.id) AND (clm.is_active = true))) AS assigned_modules_count,
    ( SELECT count(*) AS count
           FROM (educational_content.assignments a
             JOIN social_features.assignment_classrooms ac ON ((ac.assignment_id = a.id)))
          WHERE ((ac.classroom_id = c.id) AND (a.is_published = true))) AS active_assignments_count,
    COALESCE(( SELECT (avg(us.total_xp))::integer AS avg
           FROM (gamification_system.user_stats us
             JOIN social_features.classroom_members cm ON ((cm.student_id = us.user_id)))
          WHERE ((cm.classroom_id = c.id) AND (cm.is_active = true))), 0) AS avg_student_xp,
    COALESCE(( SELECT (avg(us.level))::numeric(4,1) AS avg
           FROM (gamification_system.user_stats us
             JOIN social_features.classroom_members cm ON ((cm.student_id = us.user_id)))
          WHERE ((cm.classroom_id = c.id) AND (cm.is_active = true))), (1)::numeric) AS avg_student_level,
    COALESCE(( SELECT (avg(us.exercises_completed))::integer AS avg
           FROM (gamification_system.user_stats us
             JOIN social_features.classroom_members cm ON ((cm.student_id = us.user_id)))
          WHERE ((cm.classroom_id = c.id) AND (cm.is_active = true))), 0) AS avg_exercises_completed,
    ( SELECT count(DISTINCT cm.student_id) AS count
           FROM (social_features.classroom_members cm
             JOIN gamification_system.user_stats us ON ((us.user_id = cm.student_id)))
          WHERE ((cm.classroom_id = c.id) AND (cm.is_active = true) AND (us.last_activity_at >= (now() - '7 days'::interval)))) AS active_students_week,
    now() AS snapshot_timestamp
   FROM social_features.classrooms c
  WHERE (is_active = true)
  WITH NO DATA;


