-- Name: teacher_contents; Type: TABLE; Schema: educational_content; Owner: postgres
--

CREATE TABLE educational_content.teacher_contents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    teacher_id uuid NOT NULL,
    tenant_id uuid,
    title character varying(255) NOT NULL,
    description text,
    content_type character varying(50) NOT NULL,
    content_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    instructions text,
    learning_objectives jsonb DEFAULT '[]'::jsonb,
    prerequisites jsonb DEFAULT '[]'::jsonb,
    subject_area character varying(100),
    grade_level character varying(50),
    difficulty_level character varying(20),
    estimated_duration_minutes integer,
    media_resources jsonb DEFAULT '[]'::jsonb,
    attachments jsonb DEFAULT '[]'::jsonb,
    target_classrooms jsonb DEFAULT '[]'::jsonb,
    visibility character varying(50) DEFAULT 'private'::character varying,
    is_shared boolean DEFAULT false,
    shared_with_teachers jsonb DEFAULT '[]'::jsonb,
    allow_modifications boolean DEFAULT false,
    status character varying(50) DEFAULT 'draft'::character varying,
    published_at timestamp with time zone,
    published_version integer DEFAULT 1,
    requires_approval boolean DEFAULT false,
    approved_by uuid,
    approved_at timestamp with time zone,
    times_assigned integer DEFAULT 0,
    times_completed integer DEFAULT 0,
    average_score numeric(5,2),
    average_duration_minutes integer,
    tags jsonb DEFAULT '[]'::jsonb,
    keywords jsonb DEFAULT '[]'::jsonb,
    points_value integer DEFAULT 0,
    ml_coins_reward integer DEFAULT 0,
    student_rating numeric(3,2),
    rating_count integer DEFAULT 0,
    teacher_rating numeric(3,2),
    teacher_rating_count integer DEFAULT 0,
    license character varying(100),
    attribution text,
    based_on_content_id uuid,
    version_number integer DEFAULT 1,
    is_latest_version boolean DEFAULT true,
    previous_version_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb,
    is_active boolean DEFAULT true,
    is_featured boolean DEFAULT false,
    is_template boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone,
    CONSTRAINT teacher_contents_difficulty_valid CHECK (((difficulty_level IS NULL) OR ((difficulty_level)::text = ANY ((ARRAY['easy'::character varying, 'medium'::character varying, 'hard'::character varying, 'expert'::character varying])::text[])))),
    CONSTRAINT teacher_contents_duration_positive CHECK (((estimated_duration_minutes IS NULL) OR (estimated_duration_minutes > 0))),
    CONSTRAINT teacher_contents_points_non_negative CHECK (((points_value >= 0) AND (ml_coins_reward >= 0))),
    CONSTRAINT teacher_contents_status_valid CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'pending_review'::character varying, 'approved'::character varying, 'published'::character varying, 'archived'::character varying])::text[]))),
    CONSTRAINT teacher_contents_type_valid CHECK (((content_type)::text = ANY ((ARRAY['custom_exercise'::character varying, 'worksheet'::character varying, 'reading_material'::character varying, 'video_lesson'::character varying, 'presentation'::character varying, 'quiz'::character varying, 'assignment'::character varying, 'resource_pack'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT teacher_contents_visibility_valid CHECK (((visibility)::text = ANY ((ARRAY['private'::character varying, 'classroom'::character varying, 'school'::character varying, 'public'::character varying])::text[])))
);


ALTER TABLE educational_content.teacher_contents OWNER TO postgres;

--
-- Name: TABLE teacher_contents; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON TABLE educational_content.teacher_contents IS 'RLS enabled: Contenido docente - teacher own + student read public';


