-- Name: COLUMN teacher_contents.content_data; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON COLUMN educational_content.teacher_contents.content_data IS 'JSONB containing the actual content structure, varies by content_type. Examples: exercises (questions, answers), worksheets (sections), videos (url, chapters), presentations (slides)';


