CREATE TABLE system_configuration.feature_flags (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    flag_key character varying(100) NOT NULL,
    flag_name character varying(255) NOT NULL,
    description text,
    category character varying(50),
    is_enabled boolean DEFAULT false NOT NULL,
    is_system_wide boolean DEFAULT true NOT NULL,
    rollout_percentage integer DEFAULT 100,
    rollout_strategy character varying(50) DEFAULT 'all'::character varying,
    target_users uuid[] DEFAULT ARRAY[]::uuid[],
    target_roles auth_management.gamilit_role[] DEFAULT ARRAY[]::auth_management.gamilit_role[],
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    depends_on_flags jsonb DEFAULT '[]'::jsonb,
    conflicts_with jsonb DEFAULT '[]'::jsonb,
    default_value jsonb DEFAULT 'true'::jsonb,
    config_schema jsonb,
    config_options jsonb DEFAULT '{}'::jsonb,
    tenant_overrides jsonb DEFAULT '{}'::jsonb,
    classroom_overrides jsonb DEFAULT '{}'::jsonb,
    required_role character varying(50),
    is_user_configurable boolean DEFAULT false,
    tags jsonb DEFAULT '[]'::jsonb,
    documentation_url text,
    changelog text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    enabled_at timestamp with time zone,
    disabled_at timestamp with time zone,
    deprecated_at timestamp with time zone,
    will_be_removed_at timestamp with time zone,
    CONSTRAINT feature_flags_rollout_percentage_valid CHECK (((rollout_percentage >= 0) AND (rollout_percentage <= 100))),
    CONSTRAINT feature_flags_rollout_strategy_valid CHECK (((rollout_strategy)::text = ANY ((ARRAY['all'::character varying, 'percentage'::character varying, 'whitelist'::character varying, 'beta_users'::character varying, 'gradual'::character varying])::text[])))
);


