    last_name text,
    email text NOT NULL,
    avatar_url text,
    grade_level text,
    school_id uuid,
    school_name text,
    current_rank text,
    current_level integer,
    total_xp integer,
    ml_coins_balance integer,
    status text DEFAULT 'active'::text NOT NULL,
    role text DEFAULT 'student'::text NOT NULL,
    registration_date date NOT NULL,
    first_activity_date date,
    last_activity_date date,
    effective_date date NOT NULL,
    expiration_date date,
    is_current boolean DEFAULT true NOT NULL,
    version_number integer DEFAULT 1 NOT NULL,
    source_updated_at timestamp with time zone,
    etl_loaded_at timestamp with time zone DEFAULT now(),
    etl_batch_id text,
    CONSTRAINT dim_students_dates_check CHECK (((expiration_date IS NULL) OR (expiration_date >= effective_date))),
    CONSTRAINT dim_students_role_check CHECK ((role = ANY (ARRAY['student'::text, 'admin_teacher'::text, 'super_admin'::text, 'parent'::text]))),
    CONSTRAINT dim_students_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'suspended'::text, 'pending'::text])))
);


