    CONSTRAINT fact_teacher_metrics_completion_check CHECK (((completion_rate IS NULL) OR ((completion_rate >= (0)::numeric) AND (completion_rate <= (100)::numeric)))),
    CONSTRAINT fact_teacher_metrics_pass_rate_check CHECK (((pass_rate IS NULL) OR ((pass_rate >= (0)::numeric) AND (pass_rate <= (100)::numeric))))
