--
-- Name: v_ml_at_risk_students; Type: VIEW; Schema: data_warehouse; Owner: postgres
--

CREATE VIEW data_warehouse.v_ml_at_risk_students AS
 SELECT DISTINCT ON (student_id) student_id,
    classroom_id,
    tenant_id,
    (output_json ->> 'riskLevel'::text) AS risk_level,
    ((output_json ->> 'probability'::text))::numeric(5,3) AS dropout_probability,
    confidence,
    created_at AS last_prediction_at
   FROM data_warehouse.ml_prediction_logs
  WHERE (((model_type)::text = 'dropout_risk'::text) AND (created_at > (now() - '24:00:00'::interval)))
  ORDER BY student_id, created_at DESC;


