--
-- Name: content_approvals; Type: TABLE; Schema: educational_content; Owner: postgres
--

CREATE TABLE educational_content.content_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    content_type character varying(50) NOT NULL,
    content_id uuid NOT NULL,
    submitted_by uuid NOT NULL,
    submitted_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    status character varying(50) DEFAULT 'pending'::character varying NOT NULL,
    reviewer_notes text,
    revision_notes text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT content_approvals_content_type_check CHECK (((content_type)::text = ANY ((ARRAY['module'::character varying, 'exercise'::character varying, 'assignment'::character varying, 'resource'::character varying])::text[]))),
