-- Name: exercise_validation_audits; Type: TABLE; Schema: educational_content; Owner: postgres
--

CREATE TABLE educational_content.exercise_validation_audits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    exercise_id uuid NOT NULL,
    user_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    submitted_answer jsonb NOT NULL,
    submitted_at timestamp with time zone DEFAULT gamilit.now_mexico() NOT NULL,
    exercise_snapshot jsonb NOT NULL,
    validation_config_snapshot jsonb NOT NULL,
    is_correct boolean NOT NULL,
    score integer NOT NULL,
    max_score integer NOT NULL,
    feedback text,
    validation_details jsonb,
    validation_function_used text NOT NULL,
    validation_timestamp timestamp with time zone DEFAULT gamilit.now_mexico() NOT NULL,
    validation_duration_ms integer,
    is_recalculated boolean DEFAULT false,
    recalculated_at timestamp with time zone,
    recalculated_by uuid,
    recalculation_reason text,
    original_audit_id uuid,
    has_discrepancy boolean DEFAULT false,
    discrepancy_type text,
    discrepancy_notes text,
    client_metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT chk_validation_audit_attempt_positive CHECK ((attempt_number > 0)),
    CONSTRAINT chk_validation_audit_discrepancy_type CHECK (((has_discrepancy = false) OR ((has_discrepancy = true) AND (discrepancy_type IS NOT NULL)))),
    CONSTRAINT chk_validation_audit_recalculation_data CHECK (((is_recalculated = false) OR ((is_recalculated = true) AND (recalculated_at IS NOT NULL) AND (recalculation_reason IS NOT NULL)))),
    CONSTRAINT chk_validation_audit_score_range CHECK (((score >= 0) AND (score <= max_score)))
);


ALTER TABLE educational_content.exercise_validation_audits OWNER TO postgres;

--
-- Name: TABLE exercise_validation_audits; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON TABLE educational_content.exercise_validation_audits IS 'Auditoría completa de todas las validaciones de ejercicios.
Almacena snapshot inmutable de respuesta, ejercicio y configuración.
Permite trazabilidad completa y recálculo si se detectan errores.';


--
-- Name: COLUMN exercise_validation_audits.submitted_answer; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON COLUMN educational_content.exercise_validation_audits.submitted_answer IS 'Snapshot INMUTABLE de la respuesta enviada por el usuario en formato JSONB.
NO debe modificarse nunca - es la evidencia de lo que el usuario envió.';


--
-- Name: COLUMN exercise_validation_audits.exercise_snapshot; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON COLUMN educational_content.exercise_validation_audits.exercise_snapshot IS 'Snapshot del ejercicio completo en el momento de la validación.
Incluye exercise_type, content, solution, max_points.
Permite recalcular incluso si el ejercicio fue modificado después.';


--
-- Name: COLUMN exercise_validation_audits.validation_config_snapshot; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON COLUMN educational_content.exercise_validation_audits.validation_config_snapshot IS 'Snapshot de la configuración de validación usada.
Incluye validation_function, case_sensitive, allow_partial_credit, etc.
Permite recalcular con la misma configuración original.';


--
-- Name: COLUMN exercise_validation_audits.is_recalculated; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON COLUMN educational_content.exercise_validation_audits.is_recalculated IS 'Indica si este registro es resultado de un recálculo.
Si true, original_audit_id apunta al registro original.';


--
-- Name: COLUMN exercise_validation_audits.has_discrepancy; Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON COLUMN educational_content.exercise_validation_audits.has_discrepancy IS 'Indica si se detectó una discrepancia entre validación original y recálculo.
Útil para identificar casos donde la validación cambió.';


--
-- Name: exercise_validation_configs; Type: TABLE; Schema: educational_content; Owner: postgres
--

CREATE TABLE educational_content.exercise_validation_configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    exercise_type educational_content.exercise_type NOT NULL,
    validation_function text NOT NULL,
    case_sensitive boolean DEFAULT false,
    allow_partial_credit boolean DEFAULT false,
    fuzzy_matching_threshold numeric(3,2),
    normalize_text boolean DEFAULT true,
    special_rules jsonb DEFAULT '{}'::jsonb,
    default_max_points integer DEFAULT 100,
    default_passing_score integer DEFAULT 70,
    description text,
    examples jsonb,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT valid_fuzzy_threshold CHECK (((fuzzy_matching_threshold IS NULL) OR ((fuzzy_matching_threshold >= 0.00) AND (fuzzy_matching_threshold <= 1.00)))),
    CONSTRAINT valid_max_points CHECK ((default_max_points > 0)),
    CONSTRAINT valid_passing_score CHECK (((default_passing_score >= 0) AND (default_passing_score <= default_max_points)))
);


ALTER TABLE educational_content.exercise_validation_configs OWNER TO postgres;

