--
-- Name: published_teacher_contents; Type: VIEW; Schema: educational_content; Owner: postgres
--

CREATE VIEW educational_content.published_teacher_contents AS
 SELECT tc.id,
    tc.teacher_id,
    p.display_name AS teacher_name,
    tc.title,
    tc.description,
    tc.content_type,
    tc.subject_area,
    tc.grade_level,
    tc.difficulty_level,
    tc.estimated_duration_minutes,
    tc.visibility,
    tc.tags,
    tc.points_value,
    tc.ml_coins_reward,
    tc.student_rating,
    tc.rating_count,
    tc.teacher_rating,
    tc.teacher_rating_count,
    tc.times_assigned,
    tc.times_completed,
    tc.is_featured,
    tc.is_template,
    tc.license,
    tc.published_at,
    tc.created_at
   FROM (educational_content.teacher_contents tc
     JOIN auth_management.profiles p ON ((p.id = tc.teacher_id)))
  WHERE (((tc.status)::text = 'published'::text) AND (tc.is_active = true))
  ORDER BY tc.is_featured DESC, tc.published_at DESC;


ALTER VIEW educational_content.published_teacher_contents OWNER TO postgres;

