-- Name: lti_grade_passbacks; Type: TABLE; Schema: lti_integration; Owner: postgres
--

CREATE TABLE lti_integration.lti_grade_passbacks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    user_id uuid NOT NULL,
    consumer_id uuid NOT NULL,
    lineitem_url text NOT NULL,
    lineitem_id text,
    lineitem_label text,
    score_given numeric(5,2),
    score_maximum numeric(5,2) DEFAULT 100,
    score_percentage numeric(5,2),
    activity_progress text,
    grading_progress text,
    comment text,
    passback_status text DEFAULT 'pending'::text,
    lms_response jsonb,
    lms_response_code integer,
    error_message text,
    attempt_count integer DEFAULT 0,
    max_retries integer DEFAULT 3,
    next_retry_at timestamp with time zone,
    graded_at timestamp with time zone,
    first_sent_at timestamp with time zone,
    last_sent_at timestamp with time zone,
    success_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT lti_grade_passbacks_activity_progress_check CHECK ((activity_progress = ANY (ARRAY['Initialized'::text, 'Started'::text, 'InProgress'::text, 'Submitted'::text, 'Completed'::text]))),
    CONSTRAINT lti_grade_passbacks_grading_progress_check CHECK ((grading_progress = ANY (ARRAY['NotReady'::text, 'Failed'::text, 'Pending'::text, 'PendingManual'::text, 'FullyGraded'::text, 'Processed'::text]))),
    CONSTRAINT lti_grade_passbacks_passback_status_check CHECK ((passback_status = ANY (ARRAY['pending'::text, 'sending'::text, 'success'::text, 'failed'::text, 'retrying'::text])))
);

