    winner_bonus_multiplier numeric(3,2) DEFAULT 1.5,
    allow_spectators boolean DEFAULT true,
    is_public boolean DEFAULT true,
    requires_approval boolean DEFAULT false,
    custom_rules jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT peer_challenges_challenge_type_check CHECK ((challenge_type = ANY (ARRAY['head_to_head'::text, 'multiplayer'::text, 'tournament'::text, 'leaderboard'::text]))),
    CONSTRAINT peer_challenges_status_check CHECK ((status = ANY (ARRAY['open'::text, 'full'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text, 'expired'::text])))
);


