    CONSTRAINT scheduled_reports_preferred_hour_check CHECK (((preferred_hour IS NULL) OR ((preferred_hour >= 0) AND (preferred_hour <= 23)))),
    CONSTRAINT scheduled_reports_report_format_check CHECK (((report_format)::text = ANY ((ARRAY['pdf'::character varying, 'excel'::character varying, 'csv'::character varying])::text[]))),
    CONSTRAINT scheduled_reports_report_type_check CHECK (((report_type)::text = ANY ((ARRAY['individual'::character varying, 'classroom'::character varying, 'progress'::character varying, 'analytics'::character varying])::text[]))),
    CONSTRAINT scheduled_reports_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'paused'::character varying, 'completed'::character varying])::text[])))
);


