-- Name: user_reports; Type: TABLE; Schema: social_features; Owner: gamilit_user
--

CREATE TABLE social_features.user_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reporter_id uuid NOT NULL,
    report_type character varying(50) NOT NULL,
    reported_user_id uuid,
    reported_entity_id uuid,
    reported_entity_type character varying(50),
    reason character varying(100) NOT NULL,
    description text,
    evidence_urls text[],
    status character varying(50) DEFAULT 'open'::character varying NOT NULL,
    priority character varying(20) DEFAULT 'normal'::character varying NOT NULL,
    assigned_to uuid,
    resolution character varying(100),
    resolution_notes text,
    action_taken character varying(100),
    resolved_by uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT user_reports_action_taken_check CHECK (((action_taken IS NULL) OR ((action_taken)::text = ANY ((ARRAY['warning_issued'::character varying, 'content_removed'::character varying, 'user_suspended'::character varying, 'user_banned'::character varying, 'none'::character varying, 'education_provided'::character varying, 'account_restricted'::character varying])::text[])))),
    CONSTRAINT user_reports_entity_type_requires_entity CHECK ((((report_type)::text = 'user'::text) OR ((reported_entity_id IS NOT NULL) AND (reported_entity_type IS NOT NULL)))),
    CONSTRAINT user_reports_no_self_report CHECK (((reporter_id <> reported_user_id) OR (reported_user_id IS NULL))),
    CONSTRAINT user_reports_priority_check CHECK (((priority)::text = ANY ((ARRAY['low'::character varying, 'normal'::character varying, 'high'::character varying, 'urgent'::character varying, 'critical'::character varying])::text[]))),
    CONSTRAINT user_reports_reason_check CHECK (((reason)::text = ANY ((ARRAY['harassment'::character varying, 'spam'::character varying, 'inappropriate'::character varying, 'cheating'::character varying, 'hate_speech'::character varying, 'impersonation'::character varying, 'privacy_violation'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT user_reports_report_type_check CHECK (((report_type)::text = ANY ((ARRAY['user'::character varying, 'message'::character varying, 'content'::character varying, 'challenge'::character varying, 'guild'::character varying, 'team'::character varying, 'classroom'::character varying])::text[]))),
    CONSTRAINT user_reports_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'under_review'::character varying, 'resolved'::character varying, 'dismissed'::character varying, 'escalated'::character varying])::text[]))),
    CONSTRAINT user_reports_user_type_requires_user_id CHECK ((((report_type)::text <> 'user'::text) OR (reported_user_id IS NOT NULL)))
);


ALTER TABLE social_features.user_reports OWNER TO gamilit_user;

