--
-- Name: COLUMN rate_limits.resource_type; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.rate_limits.resource_type IS 'Tipo de recurso a limitar: endpoint (URL) u operation (acción lógica)';


--
-- Name: COLUMN rate_limits.resource_identifier; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.rate_limits.resource_identifier IS 'Identificador del recurso. Ejemplos:
- endpoint: /api/auth/login, /api/exercises/:id
