--
-- Name: audit_logs; Type: ROW SECURITY; Schema: audit_logging; Owner: gamilit_user
--

ALTER TABLE audit_logging.audit_logs ENABLE ROW LEVEL SECURITY;

--
-- Name: audit_logs audit_logs_admin_only; Type: POLICY; Schema: audit_logging; Owner: gamilit_user
--

CREATE POLICY audit_logs_admin_only ON audit_logging.audit_logs TO authenticated USING ((EXISTS ( SELECT 1
   FROM (auth_management.profiles p
     JOIN auth_management.user_roles ur ON ((p.id = ur.user_id)))
