--
-- Name: user_stats user_stats_read_friends; Type: POLICY; Schema: gamification_system; Owner: postgres
--

CREATE POLICY user_stats_read_friends ON gamification_system.user_stats FOR SELECT USING ((user_id IN ( SELECT friendships.friend_id
   FROM social_features.friendships
  WHERE ((friendships.user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND ((friendships.status)::text = 'accepted'::text))
UNION
 SELECT friendships.user_id
   FROM social_features.friendships
  WHERE ((friendships.friend_id = (current_setting('app.current_user_id'::text, true))::uuid) AND ((friendships.status)::text = 'accepted'::text)))));


--
-- Name: POLICY user_stats_read_friends ON user_stats; Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON POLICY user_stats_read_friends ON gamification_system.user_stats IS 'Social comparison: Users can see stats of accepted friends';


