--

COMMENT ON POLICY user_stats_read_own ON gamification_system.user_stats IS 'Users can see their own detailed statistics';


--
-- Name: user_stats user_stats_read_teacher; Type: POLICY; Schema: gamification_system; Owner: postgres
--

CREATE POLICY user_stats_read_teacher ON gamification_system.user_stats FOR SELECT USING (((EXISTS ( SELECT 1
   FROM auth_management.user_roles ur
  WHERE ((ur.user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND (ur.role = 'admin_teacher'::auth_management.gamilit_role)))) AND (user_id IN ( SELECT cm.student_id
   FROM (social_features.classroom_members cm
     JOIN social_features.classrooms c ON ((c.id = cm.classroom_id)))
  WHERE (c.teacher_id = (current_setting('app.current_user_id'::text, true))::uuid)))));


--
-- Name: POLICY user_stats_read_teacher ON user_stats; Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON POLICY user_stats_read_teacher ON gamification_system.user_stats IS 'Teachers can monitor statistics of students in their classrooms';


