--

CREATE POLICY user_stats_update_system ON gamification_system.user_stats FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM auth_management.user_roles ur
  WHERE ((ur.user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND (ur.role = 'super_admin'::auth_management.gamilit_role)))));


--
-- Name: POLICY user_stats_update_system ON user_stats; Type: COMMENT; Schema: gamification_system; Owner: postgres
--

