--

CREATE POLICY teacher_view_classroom_reviews ON progress_tracking.manual_reviews FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM (((progress_tracking.exercise_submissions es
     JOIN educational_content.exercises ex ON ((es.exercise_id = ex.id)))
     JOIN progress_tracking.module_progress mp ON (((es.user_id = mp.user_id) AND (ex.module_id = mp.module_id))))
     JOIN social_features.teacher_classrooms tc ON ((tc.classroom_id = mp.classroom_id)))
  WHERE ((es.id = manual_reviews.submission_id) AND (tc.teacher_id = gamilit.get_current_user_id()) AND ((tc.role)::text = ANY ((ARRAY['owner'::character varying, 'teacher'::character varying, 'assistant'::character varying])::text[]))))));


