--
-- Name: challenge_participants challenge_participants_select_own; Type: POLICY; Schema: social_features; Owner: postgres
--

CREATE POLICY challenge_participants_select_own ON social_features.challenge_participants FOR SELECT USING (((user_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (EXISTS ( SELECT 1
   FROM social_features.peer_challenges pc
  WHERE ((pc.id = challenge_participants.challenge_id) AND (pc.created_by = (current_setting('app.current_user_id'::text, true))::uuid)))) OR (EXISTS ( SELECT 1
   FROM social_features.challenge_participants cp2
  WHERE ((cp2.challenge_id = challenge_participants.challenge_id) AND (cp2.user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND (cp2.participation_status <> 'invited'::text))))));


--
-- Name: POLICY challenge_participants_select_own ON challenge_participants; Type: COMMENT; Schema: social_features; Owner: postgres
--

COMMENT ON POLICY challenge_participants_select_own ON social_features.challenge_participants IS 'Users can see their participation, creator sees all, accepted participants see co-participants';


--
-- Name: challenge_participants challenge_participants_update_own; Type: POLICY; Schema: social_features; Owner: postgres
--

CREATE POLICY challenge_participants_update_own ON social_features.challenge_participants FOR UPDATE USING (((user_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (EXISTS ( SELECT 1
   FROM social_features.peer_challenges pc
  WHERE ((pc.id = challenge_participants.challenge_id) AND (pc.created_by = (current_setting('app.current_user_id'::text, true))::uuid)))))) WITH CHECK (((user_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (EXISTS ( SELECT 1
   FROM social_features.peer_challenges pc
  WHERE ((pc.id = challenge_participants.challenge_id) AND (pc.created_by = (current_setting('app.current_user_id'::text, true))::uuid))))));


