--

CREATE POLICY guild_members_delete_own ON social_features.guild_members FOR DELETE USING (((user_id = gamilit.get_current_user_id()) AND (NOT (((role)::text = 'leader'::text) AND (NOT (EXISTS ( SELECT 1
   FROM social_features.guild_members gm2
  WHERE ((gm2.guild_id = guild_members.guild_id) AND ((gm2.role)::text = 'leader'::text) AND (gm2.user_id <> guild_members.user_id)))))))));


