--

CREATE POLICY team_vs_team_challenges_delete_captain ON social_features.team_vs_team_challenges FOR DELETE USING ((((team_a_captain_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (created_by = (current_setting('app.current_user_id'::text, true))::uuid)) AND ((status)::text = ANY ((ARRAY['pending'::character varying, 'cancelled'::character varying, 'declined'::character varying, 'expired'::character varying])::text[]))));


