--
-- Name: team_vs_team_challenges team_vs_team_challenges_insert_authenticated; Type: POLICY; Schema: social_features; Owner: gamilit_user
--

CREATE POLICY team_vs_team_challenges_insert_authenticated ON social_features.team_vs_team_challenges FOR INSERT WITH CHECK (((created_by = (current_setting('app.current_user_id'::text, true))::uuid) AND (team_a_captain_id = (current_setting('app.current_user_id'::text, true))::uuid) AND ((current_setting('app.current_user_id'::text, true))::uuid = ANY (team_a_members))));


--
-- Name: POLICY team_vs_team_challenges_insert_authenticated ON team_vs_team_challenges; Type: COMMENT; Schema: social_features; Owner: gamilit_user
--

COMMENT ON POLICY team_vs_team_challenges_insert_authenticated ON social_features.team_vs_team_challenges IS 'Usuarios autenticados pueden crear desafios siendo capitan y miembro del equipo A';


