--

CREATE POLICY team_vs_team_challenges_select_participant ON social_features.team_vs_team_challenges FOR SELECT USING ((((current_setting('app.current_user_id'::text, true))::uuid = ANY (team_a_members)) OR ((current_setting('app.current_user_id'::text, true))::uuid = ANY (team_b_members)) OR (team_a_captain_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (team_b_captain_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (created_by = (current_setting('app.current_user_id'::text, true))::uuid)));


--
-- Name: POLICY team_vs_team_challenges_select_participant ON team_vs_team_challenges; Type: COMMENT; Schema: social_features; Owner: gamilit_user
--

COMMENT ON POLICY team_vs_team_challenges_select_participant ON social_features.team_vs_team_challenges IS 'Usuarios pueden ver desafios donde son participantes (miembros de Team A o Team B) o capitanes';


