CREATE POLICY team_vs_team_challenges_update_captain ON social_features.team_vs_team_challenges FOR UPDATE USING (((team_a_captain_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (team_b_captain_id = (current_setting('app.current_user_id'::text, true))::uuid))) WITH CHECK (((team_a_captain_id = (current_setting('app.current_user_id'::text, true))::uuid) OR (team_b_captain_id = (current_setting('app.current_user_id'::text, true))::uuid)));


--
-- Name: POLICY team_vs_team_challenges_update_captain ON team_vs_team_challenges; Type: COMMENT; Schema: social_features; Owner: gamilit_user
--

COMMENT ON POLICY team_vs_team_challenges_update_captain ON social_features.team_vs_team_challenges IS 'Solo los capitanes de equipo pueden actualizar el desafio';


