   FROM auth_management.profiles p
  WHERE ((p.id = (current_setting('app.current_user_id'::text, true))::uuid) AND (p.role = ANY (ARRAY['admin_teacher'::auth_management.gamilit_role, 'super_admin'::auth_management.gamilit_role])))))))) WITH CHECK ((EXISTS ( SELECT 1
